#include "args.h"
#include <algorithm>
#include <cstring>
#include <iostream>
#include <stdexcept>

namespace fasttext {

void Args::defaults() {
  // Default values already set in header
}

void Args::setDefaults(model_name m) {
  model = m;
  if (m == model_name::sup) {
    minCount = 1;
    minCountLabel = 0;
    minn = 0;
    maxn = 0;
    lr = 0.1;
    loss = loss_name::softmax;
    bucket = 0;
  } else {
    minCount = 5;
    minn = 3;
    maxn = 6;
    lr = 0.05;
    loss = loss_name::ns;
    bucket = 2000000;
  }
}

static bool hasArg(const std::vector<std::string>& args, const std::string& arg) {
  for (size_t i = 1; i < args.size(); i++) {
    if (args[i] == arg) return true;
  }
  return false;
}

void Args::parseArgs(const std::vector<std::string>& args) {
  std::string command = args[0];
  for (size_t i = 1; i < args.size(); i++) {
    if (args[i][0] != '-') {
      throw std::invalid_argument("Provided argument without a dash! Usage: word2vec [-arguments]");
    }
    std::string arg = args[i].substr(1);
    // Handle double dash
    if (arg[0] == '-') arg = arg.substr(1);

    if (arg == "input") {
      input = args.at(++i);
    } else if (arg == "output") {
      output = args.at(++i);
    } else if (arg == "lr") {
      lr = std::stod(args.at(++i));
    } else if (arg == "lrUpdateRate") {
      lrUpdateRate = std::stoi(args.at(++i));
    } else if (arg == "dim") {
      dim = std::stoi(args.at(++i));
    } else if (arg == "ws") {
      ws = std::stoi(args.at(++i));
    } else if (arg == "epoch") {
      epoch = std::stoi(args.at(++i));
    } else if (arg == "minCount") {
      minCount = std::stoi(args.at(++i));
    } else if (arg == "minCountLabel") {
      minCountLabel = std::stoi(args.at(++i));
    } else if (arg == "neg") {
      neg = std::stoi(args.at(++i));
    } else if (arg == "wordNgrams") {
      wordNgrams = std::stoi(args.at(++i));
    } else if (arg == "loss") {
      std::string lossStr = args.at(++i);
      if (lossStr == "hs") loss = loss_name::hs;
      else if (lossStr == "ns") loss = loss_name::ns;
      else if (lossStr == "softmax") loss = loss_name::softmax;
      else if (lossStr == "one-vs-all" || lossStr == "ova") loss = loss_name::ova;
      else throw std::invalid_argument("Unknown loss: " + lossStr);
    } else if (arg == "model") {
      // Not really used in CLI since it's inferred from command
    } else if (arg == "bucket") {
      bucket = std::stoi(args.at(++i));
    } else if (arg == "minn") {
      minn = std::stoi(args.at(++i));
    } else if (arg == "maxn") {
      maxn = std::stoi(args.at(++i));
    } else if (arg == "thread") {
      thread = std::stoi(args.at(++i));
    } else if (arg == "t") {
      t = std::stod(args.at(++i));
    } else if (arg == "label") {
      label = args.at(++i);
    } else if (arg == "verbose") {
      verbose = std::stoi(args.at(++i));
    } else if (arg == "pretrainedVectors") {
      pretrainedVectors = args.at(++i);
    } else if (arg == "saveOutput") {
      saveOutput = (args.at(++i) == "1" || args.at(i) == "true");
    } else if (arg == "seed") {
      seed = std::stoi(args.at(++i));
    } else if (arg == "autotune-validation") {
      autotuneValidationFile = args.at(++i);
    } else if (arg == "autotune-metric") {
      autotuneMetric = args.at(++i);
    } else if (arg == "autotune-predictions") {
      autotunePredictions = std::stoi(args.at(++i));
    } else if (arg == "autotune-duration") {
      autotuneDuration = std::stoi(args.at(++i));
    } else if (arg == "autotune-modelsize") {
      autotuneModelSize = args.at(++i);
    } else if (arg == "cutoff") {
      cutoff = std::stoi(args.at(++i));
    } else if (arg == "retrain") {
      retrain = (args.at(++i) == "1" || args.at(i) == "true");
    } else if (arg == "qnorm") {
      qnorm = (args.at(++i) == "1" || args.at(i) == "true");
    } else if (arg == "qout") {
      qout = (args.at(++i) == "1" || args.at(i) == "true");
    } else if (arg == "dsub") {
      dsub = std::stoi(args.at(++i));
    } else {
      throw std::invalid_argument("Unknown argument: " + arg);
    }
  }
}

void Args::printHelp() {
  std::cerr << "\nThe following arguments are mandatory:\n"
            << "  -input              training file path\n"
            << "  -output             output file path\n"
            << "\nThe following arguments are optional:\n"
            << "  -verbose            verbosity level [" << verbose << "]\n";
  printDictHelp();
  printOptimizationHelp();
  printQuantizationHelp();
}

void Args::printDictHelp() {
  std::cerr << "\nThe following arguments for the dictionary are optional:\n"
            << "  -minCount           minimal number of word occurences [" << minCount << "]\n"
            << "  -minCountLabel      minimal number of label occurences [" << minCountLabel << "]\n"
            << "  -wordNgrams         max length of word ngram [" << wordNgrams << "]\n"
            << "  -bucket             number of buckets [" << bucket << "]\n"
            << "  -minn               min length of char ngram [" << minn << "]\n"
            << "  -maxn               max length of char ngram [" << maxn << "]\n"
            << "  -t                  sampling threshold [" << t << "]\n"
            << "  -label              labels prefix [" << label << "]\n";
}

void Args::printOptimizationHelp() {
  std::cerr << "\nThe following arguments for training are optional:\n"
            << "  -lr                 learning rate [" << lr << "]\n"
            << "  -lrUpdateRate       change the rate of updates for the learning rate [" << lrUpdateRate << "]\n"
            << "  -dim                size of word vectors [" << dim << "]\n"
            << "  -ws                 size of the context window [" << ws << "]\n"
            << "  -epoch              number of epochs [" << epoch << "]\n"
            << "  -neg                number of negatives sampled [" << neg << "]\n"
            << "  -loss               loss function {ns, hs, softmax, one-vs-all} [";
  switch (loss) {
    case loss_name::hs: std::cerr << "hs"; break;
    case loss_name::ns: std::cerr << "ns"; break;
    case loss_name::softmax: std::cerr << "softmax"; break;
    case loss_name::ova: std::cerr << "one-vs-all"; break;
  }
  std::cerr << "]\n"
            << "  -thread             number of threads (set to 1 to ensure reproducible results) [" << thread << "]\n"
            << "  -pretrainedVectors  pretrained word vectors for supervised learning [" << pretrainedVectors << "]\n"
            << "  -saveOutput         whether output params should be saved [" << (saveOutput ? "true" : "false") << "]\n"
            << "  -seed               random generator seed  [" << seed << "]\n";

  std::cerr << "\nThe following arguments are for autotune:\n"
            << "  -autotune-validation            validation file to be used for evaluation\n"
            << "  -autotune-metric                metric objective {f1, f1:labelname} [" << autotuneMetric << "]\n"
            << "  -autotune-predictions           number of predictions used for evaluation  [" << autotunePredictions << "]\n"
            << "  -autotune-duration              maximum duration in seconds [" << autotuneDuration << "]\n"
            << "  -autotune-modelsize             constraint model file size [" << autotuneModelSize << "] (empty = do not quantize)\n";
}

void Args::printQuantizationHelp() {
  std::cerr << "\nThe following arguments for quantization are optional:\n"
            << "  -cutoff             number of words and ngrams to retain [" << cutoff << "]\n"
            << "  -retrain            whether embeddings are finetuned if a cutoff is applied [" << (retrain ? "true" : "false") << "]\n"
            << "  -qnorm              whether the norm is quantized separately [" << (qnorm ? "true" : "false") << "]\n"
            << "  -qout               whether the classifier is quantized [" << (qout ? "true" : "false") << "]\n"
            << "  -dsub               size of each sub-vector [" << dsub << "]\n";
}

static void writeString(std::ostream& out, const std::string& s) {
  out.write(s.c_str(), s.size() + 1); // include null terminator
}

static std::string readString(std::istream& in) {
  std::string s;
  char c;
  while (in.get(c) && c != '\0') s += c;
  return s;
}

void Args::save(std::ostream& out) const {
  out.write(reinterpret_cast<const char*>(&dim), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&ws), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&epoch), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&minCount), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&neg), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&wordNgrams), sizeof(int32_t));
  int32_t loss_i = static_cast<int32_t>(loss);
  int32_t model_i = static_cast<int32_t>(model);
  out.write(reinterpret_cast<const char*>(&loss_i), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&model_i), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&bucket), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&minn), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&maxn), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&lrUpdateRate), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&t), sizeof(double));
}

void Args::load(std::istream& in) {
  in.read(reinterpret_cast<char*>(&dim), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&ws), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&epoch), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&minCount), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&neg), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&wordNgrams), sizeof(int32_t));
  int32_t loss_i, model_i;
  in.read(reinterpret_cast<char*>(&loss_i), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&model_i), sizeof(int32_t));
  loss = static_cast<loss_name>(loss_i);
  model = static_cast<model_name>(model_i);
  in.read(reinterpret_cast<char*>(&bucket), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&minn), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&maxn), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&lrUpdateRate), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&t), sizeof(double));
}

void Args::dump(std::ostream& out) const {
  out << "dim " << dim << "\n";
  out << "ws " << ws << "\n";
  out << "epoch " << epoch << "\n";
  out << "minCount " << minCount << "\n";
  out << "neg " << neg << "\n";
  out << "wordNgrams " << wordNgrams << "\n";
  out << "loss ";
  switch (loss) {
    case loss_name::hs: out << "hs"; break;
    case loss_name::ns: out << "ns"; break;
    case loss_name::softmax: out << "softmax"; break;
    case loss_name::ova: out << "ova"; break;
  }
  out << "\n";
  out << "model ";
  switch (model) {
    case model_name::cbow: out << "cbow"; break;
    case model_name::sg: out << "sg"; break;
    case model_name::sup: out << "sup"; break;
  }
  out << "\n";
  out << "bucket " << bucket << "\n";
  out << "minn " << minn << "\n";
  out << "maxn " << maxn << "\n";
  out << "lrUpdateRate " << lrUpdateRate << "\n";
  out << "t " << t << "\n";
}

} // namespace fasttext
