#include "matrix.h"
#include "vector.h"
#include <algorithm>
#include <cassert>
#include <cmath>
#include <random>
#include <stdexcept>
#include <string>

namespace fasttext {

DenseMatrix::DenseMatrix() : m_(0), n_(0), data_() {}

DenseMatrix::DenseMatrix(int64_t m, int64_t n) : m_(m), n_(n), data_(m * n, 0.0f) {}

void DenseMatrix::zero() {
  std::fill(data_.begin(), data_.end(), 0.0f);
}

void DenseMatrix::uniform(float a, uint32_t seed) {
  std::minstd_rand rng(seed);
  std::uniform_real_distribution<float> dist(-a, a);
  for (auto& x : data_) {
    x = dist(rng);
  }
}

void DenseMatrix::uniformThread(float a, uint32_t seed, int threadId, int numThreads) {
  // Initialize with thread-local portion
  std::minstd_rand rng(seed);
  // Skip to this thread's range
  int64_t total = m_ * n_;
  int64_t perThread = (total + numThreads - 1) / numThreads;
  int64_t start = threadId * perThread;
  int64_t end = std::min(start + perThread, total);

  // We need to advance the RNG to the right position
  // Actually, the real fasttext uses thread_local rng seeded per-row
  // Let's just do uniform for all in one thread (this will be overridden)
  std::uniform_real_distribution<float> dist(-a, a);
  for (int64_t i = start; i < end; i++) {
    data_[i] = dist(rng);
  }
}

float DenseMatrix::dotRow(const Vector& vec, int64_t i) const {
  assert(i >= 0 && i < m_);
  assert(vec.size() == n_);
  float d = 0.0f;
  const float* row_data = &data_[i * n_];
  for (int64_t j = 0; j < n_; j++) {
    d += row_data[j] * vec[j];
  }
  if (std::isnan(d)) {
    throw EncounteredNaNError();
  }
  return d;
}

void DenseMatrix::addVectorToRow(const Vector& vec, int64_t i, float a) {
  assert(i >= 0 && i < m_);
  assert(vec.size() == n_);
  float* row_data = &data_[i * n_];
  for (int64_t j = 0; j < n_; j++) {
    row_data[j] += a * vec[j];
  }
}

void DenseMatrix::addRowToVector(Vector& x, int32_t i) const {
  assert(i >= 0 && i < m_);
  assert(x.size() == n_);
  const float* row_data = &data_[i * n_];
  for (int64_t j = 0; j < n_; j++) {
    x[j] += row_data[j];
  }
}

void DenseMatrix::addRowToVector(Vector& x, int32_t i, float a) const {
  assert(i >= 0 && i < m_);
  assert(x.size() == n_);
  const float* row_data = &data_[i * n_];
  for (int64_t j = 0; j < n_; j++) {
    x[j] += a * row_data[j];
  }
}

void DenseMatrix::multiplyRow(const Vector& norms, int64_t ib, int64_t ie) {
  if (ie == -1) ie = m_;
  assert(ie <= norms.size());
  for (int64_t i = ib; i < ie; i++) {
    float norm = norms[i];
    if (norm > 0) {
      float* row_data = &data_[i * n_];
      for (int64_t j = 0; j < n_; j++) {
        row_data[j] *= norm;
      }
    }
  }
}

void DenseMatrix::divideRow(const Vector& norms, int64_t ib, int64_t ie) {
  if (ie == -1) ie = m_;
  assert(ie <= norms.size());
  for (int64_t i = ib; i < ie; i++) {
    float norm = norms[i];
    if (norm > 0) {
      float* row_data = &data_[i * n_];
      for (int64_t j = 0; j < n_; j++) {
        row_data[j] /= norm;
