#include "vector.h"
#include "matrix.h"
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <numeric>

namespace fasttext {

Vector::Vector(int64_t m) : m_(m), data_(m, 0.0f) {}

void Vector::zero() {
  std::fill(data_.begin(), data_.end(), 0.0f);
}

void Vector::mul(float a) {
  for (auto& x : data_) x *= a;
}

double Vector::norm() const {
  double sum = 0.0;
  for (auto x : data_) sum += x * x;
  return std::sqrt(sum);
}

void Vector::addVector(const Vector& source, float s) {
  for (int64_t i = 0; i < m_; i++) {
    data_[i] += s * source.data_[i];
  }
}

void Vector::addRow(const DenseMatrix& A, int64_t i, float s) {
  assert(i >= 0);
  assert(i < A.rows());
  assert(m_ == A.cols());
  A.addRowToVector(*this, i, s);
}

void Vector::mul(const DenseMatrix& A, const Vector& vec) {
  assert(A.cols() == vec.size());
  assert(A.rows() == m_);
  for (int64_t i = 0; i < m_; i++) {
    data_[i] = A.dotRow(vec, i);
  }
}

int64_t Vector::argmax() const {
  int64_t idx = 0;
  for (int64_t i = 1; i < m_; i++) {
    if (data_[i] > data_[idx]) idx = i;
  }
  return idx;
}

std::ostream& operator<<(std::ostream& out, const Vector& v) {
  for (int64_t i = 0; i < v.m_; i++) {
    out << v.data_[i];
    if (i < v.m_ - 1) out << " ";
  }
  return out;
}

