#include "dictionary.h"
#include "args.h"
#include <cassert>
#include <cmath>
#include <fstream>
#include <iostream>
#include <sstream>
#include <algorithm>
#include <stdexcept>

namespace fasttext {

const std::string Dictionary::EOS = "</s>";
const std::string Dictionary::BOW = "<";
const std::string Dictionary::EOW = ">";

Dictionary::Dictionary(std::shared_ptr<const Args> args)
    : args_(args),
      word2int_(MAX_VOCAB_SIZE, -1),
      size_(0),
      nwords_(0),
      nlabels_(0),
      ntokens_(0),
      pruneidx_size_(-1) {}

Dictionary::Dictionary(std::shared_ptr<const Args> args, std::istream& in)
    : args_(args),
      word2int_(MAX_VOCAB_SIZE, -1),
      size_(0),
      nwords_(0),
      nlabels_(0),
      ntokens_(0),
      pruneidx_size_(-1) {
  load(in);
}

int32_t Dictionary::nwords() const { return nwords_; }
int32_t Dictionary::nlabels() const { return nlabels_; }
int64_t Dictionary::ntokens() const { return ntokens_; }

uint32_t Dictionary::hash(const std::string& str) const {
  uint32_t h = 2166136261;
  for (unsigned char c : str) {
    h = (h ^ c) * 16777619;
  }
  return h;
}

int32_t Dictionary::find(const std::string& w) const {
  return find(w, hash(w));
}

int32_t Dictionary::find(const std::string& w, uint32_t h) const {
  int32_t wordlen = static_cast<int32_t>(w.size());
  int32_t id = static_cast<int32_t>(h) % MAX_VOCAB_SIZE;
  while (word2int_[id] != -1 && words_[word2int_[id]].word != w) {
    id = (id + 1) % MAX_VOCAB_SIZE;
  }
  return id;
}

void Dictionary::add(const std::string& w) {
  int32_t h = find(w);
  ntokens_++;
  if (word2int_[h] == -1) {
    entry e;
    e.word = w;
    e.count = 1;
    e.type = (w.substr(0, args_->label.size()) == args_->label) ? entry_type::label : entry_type::word;
    words_.push_back(std::move(e));
    word2int_[h] = size_++;
  } else {
    words_[word2int_[h]].count++;
  }
}

int32_t Dictionary::getId(const std::string& w) const {
  int32_t h = find(w);
  return word2int_[h];
}

int32_t Dictionary::getId(const std::string& w, uint32_t h) const {
  int32_t pos = find(w, h);
  return word2int_[pos];
}

entry_type Dictionary::getType(int32_t id) const {
  assert(id >= 0 && id < size_);
  return words_[id].type;
}

entry_type Dictionary::getType(const std::string& w) const {
  return (w.substr(0, args_->label.size()) == args_->label) ? entry_type::label : entry_type::word;
}

std::string Dictionary::getWord(int32_t id) const {
  assert(id >= 0 && id < size_);
  return words_[id].word;
}

bool Dictionary::discard(int32_t id, float rand) const {
  assert(id >= 0 && id < nwords_);
  if (args_->model == model_name::sup) return false;
  return rand > pdiscard_[id];
}

const std::vector<int32_t>& Dictionary::getSubwords(int32_t id) const {
  assert(id >= 0 && id < nwords_);
  return words_[id].subwords;
}

const std::vector<int32_t> Dictionary::getSubwords(const std::string& word) const {
  int32_t id = getId(word);
  if (id >= 0 && id < nwords_) {
    return words_[id].subwords;
  }
  std::vector<int32_t> ngrams;
  if (word != EOS) {
    computeSubwords(BOW + word + EOW, ngrams);
  }
  return ngrams;
}

void Dictionary::getSubwords(const std::string& word, 
                              std::vector<int32_t>& ngrams,
                              std::vector<std::string>& substrings) const {
  int32_t id = getId(word);
  ngrams.clear();
  substrings.clear();
  if (id >= 0 && id < nwords_) {
    ngrams.push_back(id);
    substrings.push_back(words_[id].word);
  }
  if (word != EOS) {
    computeSubwords(BOW + word + EOW, ngrams, &substrings);
  }
}

void Dictionary::computeSubwords(const std::string& word,
                                  std::vector<int32_t>& ngrams,
                                  std::vector<std::string>* substrings) const {
  for (size_t i = 0; i < word.size(); i++) {
    // skip continuation bytes in UTF-8
    if ((word[i] & 0xC0) == 0x80) continue;
    std::string ngram;
    size_t j = i;
    int n = 1;
    while (j < word.size()) {
      ngram += word[j++];
      while (j < word.size() && (word[j] & 0xC0) == 0x80) {
        ngram += word[j++];
      }
      if (n >= args_->minn && !(n == 1 && (i == 0 || j == word.size()))) {
        int32_t h = static_cast<int32_t>(hash(ngram) % args_->bucket) + nwords_;
        if (!pruneidx_.empty()) {
          if (pruneidx_.count(h - nwords_) == 0) {
            n++;
            continue;
          }
          h = pruneidx_.at(h - nwords_) + nwords_;
        }
        ngrams.push_back(h);
        if (substrings) substrings->push_back(ngram);
      }
      if (n >= args_->maxn) break;
      n++;
    }
  }
}

bool Dictionary::readWord(std::istream& in, std::string& word) const {
  int c;
  std::streambuf* buf = in.rdbuf();
  word.clear();
  // skip leading spaces/newlines
  while ((c = buf->sbumpc()) != EOF) {
    if (!std::isspace(c)) {
      word += static_cast<char>(c);
      break;
    }
    if (c == '\n') return true; // end of line
  }
  if (c == EOF) return false;
  // Read until space/newline
  while ((c = buf->sbumpc()) != EOF) {
    if (std::isspace(c)) {
      if (c == '\n') {
        buf->sputbackc(c);
      }
      break;
    }
    word += static_cast<char>(c);
  }
  return true;
}

void Dictionary::readFromFile(std::istream& in) {
  std::string word;
  int64_t minThreshold = 1;
  while (readWord(in, word)) {
    add(word);
    if (ntokens_ % 1000000 == 0 && args_->verbose > 1) {
      std::cerr << "\rRead " << ntokens_ / 1000000 << "M words" << std::flush;
    }
    if (size_ > 0.75 * MAX_VOCAB_SIZE) {
      minThreshold++;
      threshold(minThreshold, minThreshold);
    }
  }
  threshold(args_->minCount, args_->minCountLabel);
  initTableDiscard();
  initNgrams();
  if (args_->verbose > 0) {
    std::cerr << "\rRead " << ntokens_ / 1000000 << "M words" << std::endl;
    std::cerr << "Number of words:  " << nwords_ << std::endl;
    std::cerr << "Number of labels: " << nlabels_ << std::endl;
  }
  if (size_ == 0) {
    throw std::invalid_argument("Empty vocabulary. Try a smaller -minCount value.");
  }
}

void Dictionary::threshold(int64_t t, int64_t tl) {
  sort(words_.begin(), words_.end(), [](const entry& e1, const entry& e2) {
    if (e1.type != e2.type) return e1.type < e2.type;
    return e1.count > e2.count;
  });

  // Remove entries below threshold
  words_.erase(std::remove_if(words_.begin(), words_.end(), [&](const entry& e) {
    return (e.type == entry_type::word && e.count < t) ||
           (e.type == entry_type::label && e.count < tl);
  }), words_.end());

  words_.shrink_to_fit();
  size_ = 0;
  nwords_ = 0;
  nlabels_ = 0;

  std::fill(word2int_.begin(), word2int_.end(), -1);

  for (auto& e : words_) {
    int32_t h = find(e.word);
    word2int_[h] = size_++;
    if (e.type == entry_type::word) nwords_++;
    else nlabels_++;
  }
}

void Dictionary::initTableDiscard() {
  pdiscard_.resize(size_);
  for (size_t i = 0; i < size_; i++) {
    float f = static_cast<float>(words_[i].count) / ntokens_;
    pdiscard_[i] = std::sqrt(args_->t / f) + args_->t / f;
  }
}

void Dictionary::initNgrams() {
