  while ((c = buf->sbumpc()) != EOF) {
    if (!std::isspace(c)) {
      word += static_cast<char>(c);
      break;
    }
    if (c == '\n') return true; // end of line
  }
  if (c == EOF) return false;
  // Read until space/newline
  while ((c = buf->sbumpc()) != EOF) {
    if (std::isspace(c)) {
      if (c == '\n') {
        buf->sputbackc(c);
      }
      break;
    }
    word += static_cast<char>(c);
  }
  return true;
}

