void Dictionary::computeSubwords(const std::string& word,
                                  std::vector<int32_t>& ngrams,
                                  std::vector<std::string>* substrings) const {
  for (size_t i = 0; i < word.size(); i++) {
    // skip continuation bytes in UTF-8
    if ((word[i] & 0xC0) == 0x80) continue;
    std::string ngram;
    size_t j = i;
    int n = 1;
    while (j < word.size()) {
      ngram += word[j++];
      while (j < word.size() && (word[j] & 0xC0) == 0x80) {
        ngram += word[j++];
      }
      if (n >= args_->minn && !(n == 1 && (i == 0 || j == word.size()))) {
        int32_t h = static_cast<int32_t>(hash(ngram) % args_->bucket) + nwords_;
        if (!pruneidx_.empty()) {
          if (pruneidx_.count(h - nwords_) == 0) {
            n++;
            continue;
          }
          h = pruneidx_.at(h - nwords_) + nwords_;
        }
        ngrams.push_back(h);
        if (substrings) substrings->push_back(ngram);
      }
      if (n >= args_->maxn) break;
      n++;
    }
  }
}

bool Dictionary::readWord(std::istream& in, std::string& word) const {
  int c;
  std::streambuf* buf = in.rdbuf();
  word.clear();
  // skip leading spaces/newlines
  while ((c = buf->sbumpc()) != EOF) {
    if (!std::isspace(c)) {
      word += static_cast<char>(c);
      break;
    }
    if (c == '\n') return true; // end of line
  }
  if (c == EOF) return false;
  // Read until space/newline
  while ((c = buf->sbumpc()) != EOF) {
    if (std::isspace(c)) {
      if (c == '\n') {
        buf->sputbackc(c);
      }
      break;
    }
    word += static_cast<char>(c);
  }
  return true;
}

