  out.write(reinterpret_cast<const char*>(&pruneidx_size_), sizeof(int64_t));
  for (const auto& e : words_) {
    out.write(e.word.c_str(), e.word.size() + 1);
    out.write(reinterpret_cast<const char*>(&e.count), sizeof(int64_t));
