  in.read(reinterpret_cast<char*>(&ntokens_), sizeof(int64_t));
  in.read(reinterpret_cast<char*>(&pruneidx_size_), sizeof(int64_t));

  for (int32_t i = 0; i < size_; i++) {
    char c;
    entry e;
    while (in.get(c) && c != '\0') e.word += c;
    in.read(reinterpret_cast<char*>(&e.count), sizeof(int64_t));
    in.read(reinterpret_cast<char*>(&e.type), sizeof(int8_t));
    words_.push_back(std::move(e));
  }

  pruneidx_.clear();
  for (int64_t i = 0; i < pruneidx_size_; i++) {
    int32_t first, second;
    in.read(reinterpret_cast<char*>(&first), sizeof(int32_t));
    in.read(reinterpret_cast<char*>(&second), sizeof(int32_t));
