    if (getType(id) == entry_type::word && !discard(id, uniform(rng))) {
      words.push_back(id);
    }
    if (token == EOS) break;
  }
  return ntokens;
}

int32_t Dictionary::getLine(std::istream& in,
                             std::vector<int32_t>& words,
                             std::vector<int32_t>& labels) const {
  std::string token;
  int32_t ntokens = 0;

  words.clear();
  labels.clear();

  if (in.eof()) {
    in.clear();
    in.seekg(0, std::ios::beg);
  }

  while (readWord(in, token)) {
    int32_t h = find(token);
    int32_t id = word2int_[h];
    if (id >= 0) {
      ntokens++;
      if (getType(id) == entry_type::word) {
        words.push_back(id);
      } else if (getType(id) == entry_type::label) {
        labels.push_back(id - nwords_);
      }
    }
    if (token == EOS) break;
  }
  return ntokens;
}

std::vector<int64_t> Dictionary::getCounts(entry_type type) const {
  std::vector<int64_t> counts;
  for (const auto& w : words_) {
    if (w.type == type) counts.push_back(w.count);
  }
  return counts;
}

void Dictionary::prune(const std::vector<int32_t>& idx) {
  std::vector<int32_t> words, ngrams;
  for (auto id : idx) {
    if (id < nwords_) words.push_back(id);
    else ngrams.push_back(id);
  }
  std::sort(words.begin(), words.end());
  std::sort(ngrams.begin(), ngrams.end());

  pruneidx_size_ = ngrams.size();
  int32_t j = 0;
  for (auto& id : ngrams) {
    pruneidx_[id - nwords_] = j++;
  }

  // Rebuild with only selected words
  std::fill(word2int_.begin(), word2int_.end(), -1);
  int32_t newSize = 0;
  std::vector<entry> newWords;
  for (auto& id : words) {
    newWords.push_back(words_[id]);
    int32_t h = find(newWords.back().word);
    word2int_[h] = newSize++;
  }
  words_ = newWords;
  size_ = newSize;
  nwords_ = words.size();

  // Reinitialize ngrams with pruned index
  initTableDiscard();
  initNgrams();
}

void Dictionary::dump(std::ostream& out) const {
  out << size_ << "\n";
  for (const auto& e : words_) {
    out << e.word << " " << e.count << " ";
    if (e.type == entry_type::word) out << "word";
    else out << "label";
    out << "\n";
  }
}

int32_t Dictionary::ngramToIdx(uint32_t h, int32_t bucket) const {
  return static_cast<int32_t>(h % bucket) + nwords_;
}

} // namespace fasttext
