#include "quantmatrix.h"
#include "vector.h"
#include <algorithm>
#include <cassert>
#include <cmath>
#include <random>
#include <stdexcept>
#include <numeric>

namespace fasttext {

QuantMatrix::QuantMatrix()
    : m_(0), n_(0), dsub_(2), lastdsub_(2), nsub_(0), ksub_(256), qnorm_(false) {}

QuantMatrix::QuantMatrix(DenseMatrix&& mat, int32_t dsub, bool qnorm)
    : m_(0), n_(0), dsub_(dsub), lastdsub_(dsub), nsub_(0), ksub_(256), qnorm_(qnorm) {
  quantize(mat, dsub, qnorm);
}

void QuantMatrix::buildCodebook(const std::vector<float>& data, int32_t k,
                                  std::vector<float>& codebook, std::vector<uint8_t>& codes,
                                  int32_t n, int32_t d) {
  // Train k-means with k centroids on n vectors of dimension d
  codebook = trainKMeans(data, n, d, k);

  // Assign codes
  codes.resize(n);
  for (int32_t i = 0; i < n; i++) {
    float best_dist = std::numeric_limits<float>::max();
    int32_t best_code = 0;
    for (int32_t j = 0; j < k; j++) {
      float dist = 0.0f;
      for (int32_t l = 0; l < d; l++) {
        float diff = data[i * d + l] - codebook[j * d + l];
        dist += diff * diff;
      }
      if (dist < best_dist) {
        best_dist = dist;
        best_code = j;
      }
    }
    codes[i] = static_cast<uint8_t>(best_code);
  }
}

std::vector<float> QuantMatrix::trainKMeans(const std::vector<float>& data, int32_t n,
                                             int32_t d, int32_t k) {
  // Simple k-means
  std::vector<float> centroids(k * d, 0.0f);

  if (n < k) {
    // Not enough data: just copy what we have
    for (int32_t i = 0; i < n; i++) {
      for (int32_t j = 0; j < d; j++) {
        centroids[i * d + j] = data[i * d + j];
      }
    }
    return centroids;
  }

  // Random init: pick k distinct random vectors
  std::minstd_rand rng(1234);
  std::vector<int32_t> indices(n);
  std::iota(indices.begin(), indices.end(), 0);
  std::shuffle(indices.begin(), indices.end(), rng);

  for (int32_t i = 0; i < k; i++) {
    for (int32_t j = 0; j < d; j++) {
      centroids[i * d + j] = data[indices[i] * d + j];
    }
  }

  std::vector<uint8_t> assignments(n, 0);

  // Run k-means iterations
  for (int32_t iter = 0; iter < 25; iter++) {
    // Assignment step
    bool changed = false;
    for (int32_t i = 0; i < n; i++) {
      float best_dist = std::numeric_limits<float>::max();
      uint8_t best_k = 0;
      for (int32_t j = 0; j < k; j++) {
        float dist = 0.0f;
        for (int32_t l = 0; l < d; l++) {
          float diff = data[i * d + l] - centroids[j * d + l];
          dist += diff * diff;
        }
        if (dist < best_dist) {
          best_dist = dist;
          best_k = static_cast<uint8_t>(j);
        }
      }
      if (assignments[i] != best_k) {
        changed = true;
        assignments[i] = best_k;
      }
    }
    if (!changed) break;

    // Update step
    std::vector<float> newCentroids(k * d, 0.0f);
    std::vector<int32_t> counts(k, 0);
    for (int32_t i = 0; i < n; i++) {
      int32_t c = assignments[i];
      counts[c]++;
      for (int32_t l = 0; l < d; l++) {
        newCentroids[c * d + l] += data[i * d + l];
      }
    }
    for (int32_t j = 0; j < k; j++) {
      if (counts[j] > 0) {
        for (int32_t l = 0; l < d; l++) {
          centroids[j * d + l] = newCentroids[j * d + l] / counts[j];
        }
      }
    }
  }

  return centroids;
}

void QuantMatrix::quantize(DenseMatrix& mat, int32_t dsub, bool qnorm) {
  m_ = mat.rows();
  n_ = mat.cols();
  dsub_ = dsub;
  qnorm_ = qnorm;
  ksub_ = 256; // 8-bit

  if (m_ < ksub_) {
    throw std::invalid_argument("Matrix too small for quantization, must have at least 256 rows");
  }

  if (qnorm_) {
    // Compute norms and normalize
    Vector norms(m_);
    mat.l2NormRow(norms);
    mat.divideRow(norms);

    // Quantize norms
    std::vector<float> normData(m_);
    for (int32_t i = 0; i < m_; i++) normData[i] = norms[i];
    buildCodebook(normData, ksub_, normCodebook_, normCodes_, m_, 1);
  }

  // Compute nsub_ and lastdsub_
  nsub_ = (n_ + dsub_ - 1) / dsub_;
  lastdsub_ = n_ - (nsub_ - 1) * dsub_;

  // Quantize each sub-vector dimension independently
  // The codebook has size nsub_ * ksub_ * dsub_
  codebook_.clear();
  codes_.resize(m_ * nsub_);

  for (int32_t s = 0; s < nsub_; s++) {
    int32_t d = (s == nsub_ - 1) ? lastdsub_ : dsub_;
    int32_t offset = s * dsub_;

    // Extract sub-vectors
    std::vector<float> subdata(m_ * d);
    for (int32_t i = 0; i < m_; i++) {
      for (int32_t l = 0; l < d; l++) {
        subdata[i * d + l] = mat.at(i, offset + l);
      }
    }

    std::vector<float> sub_codebook;
    std::vector<uint8_t> sub_codes;
    buildCodebook(subdata, ksub_, sub_codebook, sub_codes, m_, d);

    // Pad codebook to dsub_ if needed
    if (d < dsub_) {
      std::vector<float> padded_codebook(ksub_ * dsub_, 0.0f);
      for (int32_t j = 0; j < ksub_; j++) {
        for (int32_t l = 0; l < d; l++) {
          padded_codebook[j * dsub_ + l] = sub_codebook[j * d + l];
        }
      }
      codebook_.insert(codebook_.end(), padded_codebook.begin(), padded_codebook.end());
    } else {
      codebook_.insert(codebook_.end(), sub_codebook.begin(), sub_codebook.end());
    }

    for (int32_t i = 0; i < m_; i++) {
      codes_[i * nsub_ + s] = sub_codes[i];
    }
  }
}

float QuantMatrix::dotRow(const Vector& vec, int64_t i) const {
  float dot = 0.0f;

  for (int32_t s = 0; s < nsub_; s++) {
    int32_t d = (s == nsub_ - 1) ? lastdsub_ : dsub_;
    int32_t code = codes_[i * nsub_ + s];
    const float* centroid = &codebook_[s * ksub_ * dsub_ + code * dsub_];
    for (int32_t l = 0; l < d; l++) {
      dot += centroid[l] * vec[s * dsub_ + l];
    }
  }

  if (qnorm_) {
    int32_t nc = normCodes_[i];
    dot *= normCodebook_[nc];
  }

  return dot;
}

void QuantMatrix::addToVector(Vector& x, int32_t i) const {
  float norm = 1.0f;
  if (qnorm_) {
    norm = normCodebook_[normCodes_[i]];
  }

  for (int32_t s = 0; s < nsub_; s++) {
    int32_t d = (s == nsub_ - 1) ? lastdsub_ : dsub_;
    int32_t code = codes_[i * nsub_ + s];
    const float* centroid = &codebook_[s * ksub_ * dsub_ + code * dsub_];
    for (int32_t l = 0; l < d; l++) {
      x[s * dsub_ + l] += norm * centroid[l];
    }
  }
}

void QuantMatrix::save(std::ostream& out) const {
  out.write(reinterpret_cast<const char*>(&qnorm_), sizeof(bool));
  out.write(reinterpret_cast<const char*>(&m_), sizeof(int64_t));
  out.write(reinterpret_cast<const char*>(&n_), sizeof(int64_t));
  out.write(reinterpret_cast<const char*>(&dsub_), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&lastdsub_), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&nsub_), sizeof(int32_t));
  out.write(reinterpret_cast<const char*>(&ksub_), sizeof(int32_t));

  out.write(reinterpret_cast<const char*>(codebook_.data()), codebook_.size() * sizeof(float));
  out.write(reinterpret_cast<const char*>(codes_.data()), codes_.size() * sizeof(uint8_t));

  if (qnorm_) {
    out.write(reinterpret_cast<const char*>(normCodebook_.data()), normCodebook_.size() * sizeof(float));
    out.write(reinterpret_cast<const char*>(normCodes_.data()), normCodes_.size() * sizeof(uint8_t));
  }
}

void QuantMatrix::load(std::istream& in) {
  in.read(reinterpret_cast<char*>(&qnorm_), sizeof(bool));
  in.read(reinterpret_cast<char*>(&m_), sizeof(int64_t));
  in.read(reinterpret_cast<char*>(&n_), sizeof(int64_t));
  in.read(reinterpret_cast<char*>(&dsub_), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&lastdsub_), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&nsub_), sizeof(int32_t));
  in.read(reinterpret_cast<char*>(&ksub_), sizeof(int32_t));

  int64_t codebook_size = nsub_ * ksub_ * dsub_;
  codebook_.resize(codebook_size);
  in.read(reinterpret_cast<char*>(codebook_.data()), codebook_size * sizeof(float));

  codes_.resize(m_ * nsub_);
  in.read(reinterpret_cast<char*>(codes_.data()), codes_.size() * sizeof(uint8_t));

  if (qnorm_) {
    normCodebook_.resize(ksub_);
    in.read(reinterpret_cast<char*>(normCodebook_.data()), ksub_ * sizeof(float));
    normCodes_.resize(m_);
    in.read(reinterpret_cast<char*>(normCodes_.data()), m_ * sizeof(uint8_t));
  }
}

void QuantMatrix::dump(std::ostream& out) const {
  out << m_ << " " << n_ << "\n";
  // This is complex - skip full dump for now
  for (int64_t i = 0; i < m_; i++) {
    Vector v(n_);
    addToVector(v, i);
    for (int64_t j = 0; j < n_; j++) {
      if (j > 0) out << " ";
      out << v[j];
    }
    out << "\n";
  }
}

} // namespace fasttext
