#include "loss.h"
#include "model.h"
#include <algorithm>
#include <cassert>
#include <cmath>
#include <stdexcept>
#include <numeric>

namespace fasttext {

constexpr int32_t SIGMOID_TABLE_SIZE = 512;
constexpr int32_t MAX_SIGMOID = 8;
constexpr int32_t LOG_TABLE_SIZE = 512;

static float t_sigmoid[SIGMOID_TABLE_SIZE + 1];
static float t_log[LOG_TABLE_SIZE + 1];

static void initSigmoidTable() {
  for (int32_t i = 0; i <= SIGMOID_TABLE_SIZE; i++) {
    float x = (2.0f * MAX_SIGMOID / SIGMOID_TABLE_SIZE) * i - MAX_SIGMOID;
    t_sigmoid[i] = 1.0f / (1.0f + std::exp(-x));
  }
}

static void initLogTable() {
  for (int32_t i = 0; i <= LOG_TABLE_SIZE; i++) {
    float x = (float(i) + 1e-5) / LOG_TABLE_SIZE;
    t_log[i] = std::log(x);
  }
}

static float sigmoid(float x) {
  if (x < -MAX_SIGMOID) return 0.0f;
  else if (x > MAX_SIGMOID) return 1.0f;
  else {
    int32_t i = static_cast<int32_t>((x + MAX_SIGMOID) * SIGMOID_TABLE_SIZE / MAX_SIGMOID / 2);
    return t_sigmoid[i];
  }
}

static float log_(float x) {
  if (x > 1.0f) return 0.0f;
  if (x < 1e-5f) return t_log[0];
  int32_t i = static_cast<int32_t>(x * LOG_TABLE_SIZE);
  return t_log[i];
}

struct Initializer {
  Initializer() {
    initSigmoidTable();
    initLogTable();
  }
} initializer;

// Loss base class
Loss::Loss(std::shared_ptr<DenseMatrix> wo)
    : wo_(wo), loss_(0.0f), nexamples_(0) {}

void Loss::predict(int32_t k, float threshold, Predictions& heap, Model& model) const {
  computeOutput(const_cast<Model&>(model));

  const Vector& output = model.output_;
  for (int32_t i = 0; i < output.size(); i++) {
    if (output[i] >= threshold) {
      if ((int32_t)heap.size() == k) {
        // Find and replace minimum if this is larger
        auto it = std::min_element(heap.begin(), heap.end());
        if (output[i] > it->first) {
          *it = {output[i], i};
        }
      } else {
        heap.push_back({output[i], i});
      }
    }
  }

  // If we didn't fill k predictions with threshold, get top-k
  if ((int32_t)heap.size() < k) {
    heap.clear();
    std::vector<std::pair<float, int32_t>> all;
    for (int32_t i = 0; i < output.size(); i++) {
      all.push_back({output[i], i});
    }
    std::sort(all.begin(), all.end(), [](const auto& a, const auto& b) {
      return a.first > b.first;
    });
    for (int32_t i = 0; i < std::min(k, (int32_t)all.size()); i++) {
      if (all[i].first >= threshold) {
        heap.push_back(all[i]);
      }
    }
  }
}

// BinaryLogisticLoss
BinaryLogisticLoss::BinaryLogisticLoss(std::shared_ptr<DenseMatrix> wo)
    : Loss(wo) {}

float BinaryLogisticLoss::binaryLogistic(int32_t target, Model& model, bool label, 
                                           float lr, bool backprop) {
  float score = sigmoid(wo_->dotRow(model.hidden_, target));
  float alpha = lr * (float(label) - score);
  if (backprop) {
    model.grad_.addRow(*wo_, target, alpha);
    wo_->addVectorToRow(model.hidden_, target, alpha);
  }
  if (label) return -log_(score);
  else return -log_(1.0f - score);
}

float BinaryLogisticLoss::forward(const std::vector<int32_t>& targets,
                                   int32_t targetIndex,
                                   Model& model,
                                   float lr,
                                   bool backprop) {
