}

void BinaryLogisticLoss::computeOutput(Model& model) {
  // Sigmoid of each output neuron
  const int64_t osz = wo_->rows();
  for (int64_t i = 0; i < osz; i++) {
    model.output_[i] = sigmoid(wo_->dotRow(model.hidden_, i));
  }
}

