  }

  negatives_.reserve(NEGATIVE_TABLE_SIZE);
  for (int32_t i = 0; i < (int32_t)counts.size(); i++) {
    double c = std::pow(counts[i], 0.75);
    for (int32_t j = 0; j < (int32_t)(c * NEGATIVE_TABLE_SIZE / z + 0.5); j++) {
