float NegativeSamplingLoss::forward(const std::vector<int32_t>& targets,
                                     int32_t targetIndex,
                                     Model& model,
                                     float lr,
                                     bool backprop) {
  int32_t target = targets[targetIndex];
  float loss = binaryLogistic(target, model, true, lr, backprop);
  for (int32_t i = 0; i < neg_; i++) {
    int32_t negTarget = getNegative(target, model.rng_);
    loss += binaryLogistic(negTarget, model, false, lr, backprop);
  }
  return loss;
}

void NegativeSamplingLoss::computeOutput(Model& model) {
  BinaryLogisticLoss::computeOutput(model);
}

// HierarchicalSoftmaxLoss
HierarchicalSoftmaxLoss::HierarchicalSoftmaxLoss(std::shared_ptr<DenseMatrix> wo,
                                                   const std::vector<int64_t>& counts)
    : BinaryLogisticLoss(wo) {
  buildTree(counts);
}

void HierarchicalSoftmaxLoss::buildTree(const std::vector<int64_t>& counts) {
  int32_t n = static_cast<int32_t>(counts.size());
  tree_.resize(2 * n - 1);

  for (int32_t i = 0; i < 2 * n - 1; i++) {
    tree_[i].parent = -1;
    tree_[i].left = -1;
    tree_[i].right = -1;
    tree_[i].count = 1e15;
    tree_[i].binary = false;
  }

  for (int32_t i = 0; i < n; i++) {
    tree_[i].count = counts[i];
  }

  int32_t leaf = n - 1;
  int32_t node = n;
  for (int32_t i = n; i < 2 * n - 1; i++) {
    int32_t mini[2];
    for (int32_t j = 0; j < 2; j++) {
      if (leaf >= 0 && tree_[leaf].count < tree_[node].count) {
        mini[j] = leaf--;
      } else {
        mini[j] = node++;
      }
    }
    tree_[i].left = mini[0];
    tree_[i].right = mini[1];
    tree_[i].count = tree_[mini[0]].count + tree_[mini[1]].count;
    tree_[mini[0]].parent = i;
    tree_[mini[1]].parent = i;
    tree_[mini[1]].binary = true;
  }

  // Build paths and codes
  paths_.resize(n);
  codes_.resize(n);
  for (int32_t i = 0; i < n; i++) {
    int32_t node = i;
    while (tree_[node].parent != -1) {
      paths_[i].push_back(tree_[node].parent - n);
      codes_[i].push_back(tree_[node].binary);
      node = tree_[node].parent;
    }
  }
}

float HierarchicalSoftmaxLoss::forward(const std::vector<int32_t>& targets,
                                        int32_t targetIndex,
                                        Model& model,
                                        float lr,
                                        bool backprop) {
  int32_t target = targets[targetIndex];
  float loss = 0.0f;
  for (size_t i = 0; i < paths_[target].size(); i++) {
    loss += binaryLogistic(paths_[target][i], model, codes_[target][i], lr, backprop);
  }
  return loss;
}

void HierarchicalSoftmaxLoss::computeOutput(Model& model) {
  // Compute output via HS
  const int64_t osz = wo_->rows();
  // n = number of leaves = osz + 1? No...
  // Just set output to zeros for now and compute via DFS
  model.output_.zero();
  // Actually output_ is used in predict via dfs
}

void HierarchicalSoftmaxLoss::predict(int32_t k, float threshold, 
                                       Predictions& heap, Model& model) const {
  int32_t n = static_cast<int32_t>(paths_.size()); // number of leaves
  dfs(k, threshold, 2 * n - 2, 0.0f, heap, model);
  std::sort(heap.begin(), heap.end(), [](const auto& a, const auto& b) {
    return a.first > b.first;
  });
  if ((int32_t)heap.size() > k) {
    heap.resize(k);
  }
}

void HierarchicalSoftmaxLoss::dfs(int32_t k, float threshold, int32_t node, float score,
                                   Predictions& heap, Model& model) const {
  if (heap.size() == (size_t)k && score < heap.front().first) {
    return;
  }

  int32_t n = static_cast<int32_t>(paths_.size());

  if (tree_[node].left == -1 && tree_[node].right == -1) {
    // Leaf
    float prob = std::exp(score);
    if (prob >= threshold) {
      heap.push_back({prob, node});
      std::push_heap(heap.begin(), heap.end(), [](const auto& a, const auto& b) {
        return a.first > b.first;
      });
      if ((int32_t)heap.size() > k) {
        std::pop_heap(heap.begin(), heap.end(), [](const auto& a, const auto& b) {
          return a.first > b.first;
        });
        heap.pop_back();
      }
    }
    return;
  }

  float f = wo_->dotRow(model.hidden_, node - n);
  f = 1.0f / (1.0f + std::exp(-f));

  dfs(k, threshold, tree_[node].left, score + log_(1.0f - f), heap, model);
  dfs(k, threshold, tree_[node].right, score + log_(f), heap, model);
}

// SoftmaxLoss
SoftmaxLoss::SoftmaxLoss(std::shared_ptr<DenseMatrix> wo)
    : Loss(wo) {}

float SoftmaxLoss::forward(const std::vector<int32_t>& targets,
                            int32_t targetIndex,
                            Model& model,
                            float lr,
                            bool backprop) {
  const int64_t osz = wo_->rows();
  float max_score = 0.0f;
  bool first = true;

  // Compute logits
  for (int64_t i = 0; i < osz; i++) {
    model.output_[i] = wo_->dotRow(model.hidden_, i);
    if (first || model.output_[i] > max_score) {
      max_score = model.output_[i];
      first = false;
    }
  }

  // Softmax
  float z = 0.0f;
  for (int64_t i = 0; i < osz; i++) {
    model.output_[i] = std::exp(model.output_[i] - max_score);
    z += model.output_[i];
  }
  for (int64_t i = 0; i < osz; i++) {
    model.output_[i] /= z;
  }

  if (backprop) {
    int32_t target = targets[targetIndex];
    for (int64_t i = 0; i < osz; i++) {
      float label = (i == target) ? 1.0f : 0.0f;
      float alpha = lr * (label - model.output_[i]);
      model.grad_.addRow(*wo_, i, alpha);
      wo_->addVectorToRow(model.hidden_, i, alpha);
    }
  }

  return -log_(model.output_[targets[targetIndex]]);
}

void SoftmaxLoss::computeOutput(Model& model) {
  const int64_t osz = wo_->rows();
  float max_score = 0.0f;
  bool first = true;

  for (int64_t i = 0; i < osz; i++) {
    model.output_[i] = wo_->dotRow(model.hidden_, i);
    if (first || model.output_[i] > max_score) {
      max_score = model.output_[i];
      first = false;
    }
  }

  float z = 0.0f;
  for (int64_t i = 0; i < osz; i++) {
    model.output_[i] = std::exp(model.output_[i] - max_score);
    z += model.output_[i];
  }
  for (int64_t i = 0; i < osz; i++) {
    model.output_[i] /= z;
  }
}

// OneVsAllLoss
OneVsAllLoss::OneVsAllLoss(std::shared_ptr<DenseMatrix> wo)
    : BinaryLogisticLoss(wo) {}

float OneVsAllLoss::forward(const std::vector<int32_t>& targets,
                             int32_t targetIndex,
                             Model& model,
                             float lr,
                             bool backprop) {
  const int64_t osz = wo_->rows();
  float loss = 0.0f;
  for (int32_t i = 0; i < osz; i++) {
    bool isTarget = false;
    for (int32_t t : targets) {
      if (i == t) { isTarget = true; break; }
    }
    loss += binaryLogistic(i, model, isTarget, lr, backprop);
  }
  return loss;
}

void OneVsAllLoss::computeOutput(Model& model) {
  BinaryLogisticLoss::computeOutput(model);
}

