namespace fasttext {

Model::Model(std::shared_ptr<DenseMatrix> wi,
             std::shared_ptr<DenseMatrix> wo,
             std::shared_ptr<Loss> loss,
             bool normalizeGradient)
    : wi_(wi),
      wo_(wo),
      loss_(loss),
      normalizeGradient_(normalizeGradient),
      hidden_(wi->cols()),
      output_(wo->rows()),
      grad_(wi->cols()),
      rng_(1),
      hsz_(wi->cols()),
      osz_(wo->rows()) {}

void Model::computeHidden(const std::vector<int32_t>& input) {
  assert(!input.empty());
  hidden_.zero();
  for (int32_t id : input) {
    if (id < wi_->rows()) {
      hidden_.addRow(*wi_, id);
    }
  }
  hidden_.mul(1.0f / input.size());
}

float Model::predict(const std::vector<int32_t>& input,
                     int32_t target,
                     float threshold,
                     Predictions& heap) {
  if (input.empty()) {
    throw std::invalid_argument("Input must not be empty!");
  }
  computeHidden(input);
  loss_->predict(heap.size() == 0 ? 1 : heap.size(), threshold, heap, *this);
  return 0.0f; // loss not computed
}

void Model::update(const std::vector<int32_t>& input,
                   const std::vector<int32_t>& targets,
                   int32_t targetIndex,
                   float lr) {
  if (input.empty()) return;
  computeHidden(input);

  grad_.zero();

  float loss = loss_->forward(targets, targetIndex, *this, lr, true);
  loss_->loss_ += loss;
  loss_->nexamples_++;

  if (normalizeGradient_) {
    grad_.mul(1.0f / input.size());
  }

  for (int32_t id : input) {
    if (id < wi_->rows()) {
      wi_->addVectorToRow(grad_, id, 1.0f);
    }
  }
}

} // namespace fasttext
