      }

      if (!input.empty()) {
        for (int32_t i : input) {
          if (i < input_->rows()) {
            svec.addRow(*input_, i);
          }
        }
        svec.mul(1.0f / input.size());
      }
      out << svec << "\n";
    }
  } else {
