void predict(const std::vector<std::string>& args, bool printProb) {
  if (args.size() < 3) {
    std::cerr << "usage: fasttext predict[-prob] <model> <test-data> [<k>] [<th>]\n";
    exit(1);
  }

  int32_t k = 1;
  float threshold = 0.0f;
  std::string modelFile = args[1];
  std::string testFile = args[2];

  if (args.size() > 3) {
    k = std::stoi(args[3]);
  }
  if (args.size() > 4) {
    threshold = std::stof(args[4]);
  }

  FastText fasttext;
  try {
    fasttext.loadModel(modelFile);
  } catch (std::exception& e) {
    std::cerr << e.what() << std::endl;
    exit(1);
  }

  std::istream* is = &std::cin;
  std::ifstream ifs;
  if (testFile != "-") {
    ifs.open(testFile);
    if (!ifs.is_open()) {
      std::cerr << "Input file cannot be opened!" << std::endl;
      exit(1);
    }
    is = &ifs;
  }

  fasttext.predict(*is, std::cout, k, threshold, printProb);

  if (ifs.is_open()) ifs.close();
}

