void dump(const std::vector<std::string>& args) {
  if (args.size() < 3) {
    std::cerr << "usage: fasttext dump <model> <option>\n"
              << "  option: args, dict, input, output\n";
    exit(1);
  }

  FastText fasttext;
  try {
    fasttext.loadModel(args[1]);
  } catch (std::exception& e) {
    std::cerr << e.what() << std::endl;
    exit(1);
  }

  std::string option = args[2];
  if (option == "args") {
    fasttext.dumpArgs(std::cout);
  } else if (option == "dict") {
    fasttext.dumpDict(std::cout);
  } else if (option == "input") {
    fasttext.dumpInput(std::cout);
  } else if (option == "output") {
    fasttext.dumpOutput(std::cout);
  } else {
    std::cerr << "Unknown dump option: " << option << "\n";
    exit(1);
  }
}

void quantize(const std::vector<std::string>& args) {
  Args a;
  a.setDefaults(model_name::sup); // quantize inherits from sup defaults
  if (args.size() < 2) {
    std::cerr << "usage: fasttext quantize <args>\n";
    a.printHelp();
    exit(1);
  }
  try {
    a.parseArgs(args);
  } catch (std::invalid_argument& e) {
    std::cerr << e.what() << std::endl;
    a.printHelp();
    exit(1);
  }
  if (a.output.empty()) {
    std::cerr << "usage: fasttext quantize <args>\n";
    a.printHelp();
    exit(1);
  }

  FastText fasttext;
  fasttext.quantize(a);
}

int main(int argc, char** argv) {
  std::vector<std::string> args(argv, argv + argc);

  if (args.size() < 2) {
    printUsage();
    exit(1);
  }

  std::string command = args[1];

  // Remove the program name (args[0]) and command (args[1])
  // So args for commands start from index 2 but we pass index 1 onwards
  std::vector<std::string> cmdArgs(args.begin() + 2, args.end());

  if (command == "supervised") {
    supervised(cmdArgs);
  } else if (command == "skipgram") {
    skipgram(cmdArgs);
  } else if (command == "cbow") {
    cbow(cmdArgs);
  } else if (command == "predict") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    predict(pargs, false);
  } else if (command == "predict-prob") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    predict(pargs, true);
  } else if (command == "test") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    test(pargs);
  } else if (command == "test-label") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    testLabel(pargs);
  } else if (command == "print-word-vectors") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    printWordVectors(pargs);
  } else if (command == "print-sentence-vectors") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    printSentenceVectors(pargs);
  } else if (command == "print-ngrams") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    printNgrams(pargs);
  } else if (command == "nn") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    nn(pargs);
  } else if (command == "analogies") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    analogies(pargs);
  } else if (command == "dump") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    dump(pargs);
  } else if (command == "quantize") {
    std::vector<std::string> pargs(args.begin() + 1, args.end());
    quantize(pargs);
  } else {
    printUsage();
    exit(1);
  }

  return 0;
}
