#pragma once
#include "matrix.h"
#include "vector.h"
#include <memory>
#include <vector>
#include <functional>
#include <random>

namespace fasttext {

class Model;

typedef std::vector<std::pair<float, int32_t>> Predictions;

class Loss {
public:
  std::shared_ptr<DenseMatrix> wo_;
  float loss_;
  int64_t nexamples_;

  explicit Loss(std::shared_ptr<DenseMatrix> wo);
  virtual ~Loss() = default;

  virtual float forward(const std::vector<int32_t>& targets,
                        int32_t targetIndex,
                        Model& model,
                        float lr,
                        bool backprop) = 0;

  virtual void computeOutput(Model& model) const = 0;

  virtual void predict(int32_t k,
                       float threshold,
                       Predictions& heap,
                       Model& model) const;

  float getLoss() const { return nexamples_ > 0 ? loss_ / nexamples_ : 0.0f; }
  int64_t getNexamples() const { return nexamples_; }
};

// Binary Logistic loss (for negative sampling)
class BinaryLogisticLoss : public Loss {
public:
  explicit BinaryLogisticLoss(std::shared_ptr<DenseMatrix> wo);

  float binaryLogistic(int32_t target, Model& model, bool label, float lr, bool backprop);

  float forward(const std::vector<int32_t>& targets,
                int32_t targetIndex,
                Model& model,
                float lr,
                bool backprop) override;

  void computeOutput(Model& model) const override;
};

// Negative sampling loss
class NegativeSamplingLoss : public BinaryLogisticLoss {
public:
  static const int32_t NEGATIVE_TABLE_SIZE = 10000000;

  NegativeSamplingLoss(std::shared_ptr<DenseMatrix> wo,
                       int neg,
                       const std::vector<int64_t>& targetCounts);

  float forward(const std::vector<int32_t>& targets,
                int32_t targetIndex,
                Model& model,
                float lr,
                bool backprop) override;

  void computeOutput(Model& model) const override;

private:
  int neg_;
  std::vector<int32_t> negatives_;
  std::uniform_int_distribution<size_t> uniform_;

  int32_t getNegative(int32_t target, std::minstd_rand& rng);
  void initTableNegatives(const std::vector<int64_t>& counts);
};

// Hierarchical softmax loss
class HierarchicalSoftmaxLoss : public BinaryLogisticLoss {
public:
  struct Node {
    int32_t parent;
    int32_t left;
    int32_t right;
    int64_t count;
    bool binary;
  };

  HierarchicalSoftmaxLoss(std::shared_ptr<DenseMatrix> wo,
                           const std::vector<int64_t>& counts);

  float forward(const std::vector<int32_t>& targets,
                int32_t targetIndex,
                Model& model,
                float lr,
                bool backprop) override;

  void computeOutput(Model& model) const override;

  void predict(int32_t k,
               float threshold,
               Predictions& heap,
               Model& model) const override;

private:
  std::vector<std::vector<int32_t>> paths_;
  std::vector<std::vector<bool>> codes_;
  std::vector<Node> tree_;

  void buildTree(const std::vector<int64_t>& counts);
  void dfs(int32_t k, float threshold, int32_t node, float score,
           Predictions& heap, Model& model) const;
};

// Softmax loss
class SoftmaxLoss : public Loss {
public:
  explicit SoftmaxLoss(std::shared_ptr<DenseMatrix> wo);

  float forward(const std::vector<int32_t>& targets,
                int32_t targetIndex,
                Model& model,
                float lr,
                bool backprop) override;

  void computeOutput(Model& model) const override;
};

// One-vs-All loss
class OneVsAllLoss : public BinaryLogisticLoss {
public:
  explicit OneVsAllLoss(std::shared_ptr<DenseMatrix> wo);

  float forward(const std::vector<int32_t>& targets,
                int32_t targetIndex,
                Model& model,
                float lr,
