                                           float lr, bool backprop) {
  float score = sigmoid(wo_->dotRow(model.hidden_, target));
  float alpha = lr * (float(label) - score);
  if (backprop) {
    model.grad_.addRow(*wo_, target, alpha);
    wo_->addVectorToRow(model.hidden_, target, alpha);
  }
  if (label) return -log_(score);
  else return -log_(1.0f - score);
}

