void NegativeSamplingLoss::initTableNegatives(const std::vector<int64_t>& counts) {
  double z = 0.0;
  for (int64_t c : counts) {
    z += std::pow(c, 0.75);
  }

  negatives_.reserve(NEGATIVE_TABLE_SIZE);
  for (int32_t i = 0; i < (int32_t)counts.size(); i++) {
    double c = std::pow(counts[i], 0.75);
    for (int32_t j = 0; j < (int32_t)(c * NEGATIVE_TABLE_SIZE / z + 0.5); j++) {
      negatives_.push_back(i);
    }
  }

  std::shuffle(negatives_.begin(), negatives_.end(), std::minstd_rand(42));
}

