void HierarchicalSoftmaxLoss::buildTree(const std::vector<int64_t>& counts) {
  int32_t n = static_cast<int32_t>(counts.size());
  tree_.resize(2 * n - 1);

  for (int32_t i = 0; i < 2 * n - 1; i++) {
    tree_[i].parent = -1;
    tree_[i].left = -1;
    tree_[i].right = -1;
    tree_[i].count = (int64_t)1e15;
    tree_[i].binary = false;
  }

  for (int32_t i = 0; i < n; i++) {
    tree_[i].count = counts[i];
  }

  int32_t leaf = n - 1;
  int32_t node = n;
  for (int32_t i = n; i < 2 * n - 1; i++) {
    int32_t mini[2];
    for (int32_t j = 0; j < 2; j++) {
      if (leaf >= 0 && tree_[leaf].count < tree_[node].count) {
        mini[j] = leaf--;
      } else {
        mini[j] = node++;
      }
    }
    tree_[i].left = mini[0];
    tree_[i].right = mini[1];
    tree_[i].count = tree_[mini[0]].count + tree_[mini[1]].count;
    tree_[mini[0]].parent = i;
    tree_[mini[1]].parent = i;
    tree_[mini[1]].binary = true;
  }

  paths_.resize(n);
  codes_.resize(n);
  for (int32_t i = 0; i < n; i++) {
    int32_t node_i = i;
    while (tree_[node_i].parent != -1) {
      paths_[i].push_back(tree_[node_i].parent - n);
      codes_[i].push_back(tree_[node_i].binary);
      node_i = tree_[node_i].parent;
    }
  }
