             bool normalizeGradient)
    : wi_(wi),
      wo_(wo),
      loss_(loss),
      normalizeGradient_(normalizeGradient),
      hidden_(wi->cols()),
      output_(wo->rows()),
      grad_(wi->cols()),
      rng_(1),
