void Model::computeHidden(const std::vector<int32_t>& input) {
  assert(!input.empty());
  hidden_.zero();
  for (int32_t id : input) {
    if (id < (int32_t)wi_->rows()) {
      hidden_.addRow(*wi_, id);
    }
  }
  hidden_.mul(1.0f / input.size());
