float Model::predict(const std::vector<int32_t>& input,
                     int32_t target,
                     float threshold,
                     Predictions& heap) {
  if (input.empty()) {
    throw std::invalid_argument("Input must not be empty!");
  }
  computeHidden(input);
  loss_->predict(heap.size() == 0 ? 1 : (int32_t)heap.size(), threshold, heap, *this);
  return 0.0f;
}

void Model::update(const std::vector<int32_t>& input,
                   const std::vector<int32_t>& targets,
                   int32_t targetIndex,
                   float lr) {
  if (input.empty()) return;
  computeHidden(input);

  grad_.zero();

  float lossVal = loss_->forward(targets, targetIndex, *this, lr, true);
  loss_->loss_ += lossVal;
  loss_->nexamples_++;

  if (normalizeGradient_) {
    grad_.mul(1.0f / input.size());
  }

  for (int32_t id : input) {
    if (id < (int32_t)wi_->rows()) {
      wi_->addVectorToRow(grad_, id, 1.0f);
    }
  }
}

