void FastText::initMatrices() {
  int32_t nwords = dict_->nwords();
  int32_t nlabels = dict_->nlabels();
  int32_t bucket = args_->bucket;
  int32_t dim = args_->dim;

  // Input matrix: (nwords + bucket) x dim
  input_ = std::make_shared<DenseMatrix>(nwords + bucket, dim);
  uint32_t seed = static_cast<uint32_t>(args_->seed);
