static std::shared_ptr<Loss> createLoss(const Args& args,
                                         std::shared_ptr<DenseMatrix> output,
                                         const Dictionary& dict) {
  if (args.loss == loss_name::hs) {
    auto counts = dict.getCounts(entry_type::word);
    return std::make_shared<HierarchicalSoftmaxLoss>(output, counts);
  } else if (args.loss == loss_name::ns) {
    auto counts = dict.getCounts(entry_type::word);
    return std::make_shared<NegativeSamplingLoss>(output, args.neg, counts);
  } else if (args.loss == loss_name::softmax) {
    return std::make_shared<SoftmaxLoss>(output);
  } else if (args.loss == loss_name::ova) {
    return std::make_shared<OneVsAllLoss>(output);
  }
  throw std::invalid_argument("Unknown loss type");
}

void FastText::initModel() {
  auto lossFunc = createLoss(*args_, output_, *dict_);
  bool normalizeGradient = (args_->model == model_name::sup);
  model_ = std::make_shared<Model>(input_, output_, lossFunc, normalizeGradient);
}

void FastText::train(const Args& args) {
  args_ = std::make_shared<Args>(args);
  dict_ = std::make_shared<Dictionary>(args_);

  if (args_->input == "-") {
    throw std::invalid_argument("Cannot use stdin for training!");
  }

  std::ifstream ifs(args_->input);
  if (!ifs.is_open()) {
    throw std::invalid_argument(args_->input + " cannot be opened for training!");
  }

  dict_->readFromFile(ifs);
  ifs.close();

  if (!args_->pretrainedVectors.empty()) {
    loadVectors(args_->pretrainedVectors);
  } else {
    initMatrices();
  }

  initModel();

  tokenCount_ = 0;

  auto t_start = std::chrono::steady_clock::now();

  int32_t numThreads = args_->thread;
  std::vector<std::thread> threads;
  threads.reserve(numThreads);

  for (int32_t i = 0; i < numThreads; i++) {
    threads.emplace_back([this, i]() { trainThread(i); });
  }

  int64_t totalTokens = (int64_t)args_->epoch * dict_->ntokens();

  if (args_->verbose > 1) {
    while (tokenCount_ < totalTokens) {
      std::this_thread::sleep_for(std::chrono::milliseconds(100));
      double progress = (totalTokens > 0) ? 
        static_cast<double>(tokenCount_) / totalTokens : 1.0;
      if (progress > 1.0) progress = 1.0;
      double lr = args_->lr * (1.0 - progress);

      auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(
          std::chrono::steady_clock::now() - t_start).count();

      int64_t wps = (elapsed > 0) ? tokenCount_ / elapsed : 0;
      double avg_loss = model_ ? model_->loss_->getLoss() : 0.0;

      double eta = (progress > 0 && elapsed > 0) ? elapsed / progress - elapsed : 0;

      std::cerr << std::fixed
                << "\rProgress: " << std::setprecision(1) << 100.0 * progress << "% "
                << "words/sec/thread: " << wps / std::max(1, numThreads) << " "
                << "lr: " << std::setprecision(6) << lr << " "
                << "avg.loss: " << std::setprecision(6) << avg_loss << " "
                << "ETA: " << (int)(eta/3600) << "h " 
                << ((int)(eta/60)) % 60 << "m " 
                << (int)eta % 60 << "s"
                << std::flush;
    }
  }

  for (auto& t : threads) {
    t.join();
  }

  if (args_->verbose > 0) {
    auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(
        std::chrono::steady_clock::now() - t_start).count();
    int64_t wps = (elapsed > 0) ? tokenCount_ / elapsed : 0;
    double avg_loss = model_ ? model_->loss_->getLoss() : 0.0;

    std::cerr << "\rProgress: " << std::fixed << std::setprecision(1) << "100.0% "
              << "words/sec/thread: " << wps / std::max(1, numThreads) << " "
              << "lr: " << std::setprecision(6) << 0.0 << " "
              << "avg.loss: " << std::setprecision(6) << avg_loss << " "
              << "ETA:   0h 0m 0s" << std::endl;
  }

  saveModel(args_->output);
  saveVectors(args_->output);
  if (args_->saveOutput) {
    saveOutput(args_->output);
  }
}

void FastText::trainThread(int32_t threadId) {
  std::ifstream ifs(args_->input);

  ifs.seekg(0, std::ios::end);
  int64_t fileSize = ifs.tellg();
  int64_t threadStart = fileSize / args_->thread * threadId;
  ifs.seekg(threadStart);

  if (threadId > 0) {
    std::string dummy;
    std::getline(ifs, dummy);
  }

  // Create per-thread loss function (to avoid races on loss_ accumulator)
  // Actually we need to share the loss function for proper loss reporting
  // Use a local model with shared matrices
  auto lossFunc = createLoss(*args_, output_, *dict_);
  bool normalizeGradient = (args_->model == model_name::sup);
  Model localModel(input_, output_, lossFunc, normalizeGradient);
  localModel.rng_.seed(threadId);

  int64_t localTokenCount = 0;
  std::vector<int32_t> line, labels;

  int64_t totalTokens = (int64_t)args_->epoch * dict_->ntokens();

  while (tokenCount_ < totalTokens) {
    double progress = static_cast<double>(tokenCount_) / totalTokens;
    float lr = static_cast<float>(args_->lr * (1.0 - progress));
    if (lr < 1e-6f) lr = 1e-6f;

    if (args_->model == model_name::sup) {
      localTokenCount += dict_->getLine(ifs, line, labels);
      supervisedTrain(localModel, line, labels, lr);
    } else if (args_->model == model_name::cbow) {
      localTokenCount += dict_->getLine(ifs, line, localModel.rng_);
      cbowTrain(localModel, line, lr);
    } else {
      // skipgram
      localTokenCount += dict_->getLine(ifs, line, localModel.rng_);
      skipgramTrain(localModel, line, lr);
    }

    if (localTokenCount > args_->lrUpdateRate) {
      tokenCount_ += localTokenCount;
      localTokenCount = 0;

      // Sync loss to main model
      model_->loss_->loss_ += localModel.loss_->loss_;
      model_->loss_->nexamples_ += localModel.loss_->nexamples_;
      localModel.loss_->loss_ = 0.0f;
      localModel.loss_->nexamples_ = 0;
    }
  }

  tokenCount_ += localTokenCount;
  model_->loss_->loss_ += localModel.loss_->loss_;
  model_->loss_->nexamples_ += localModel.loss_->nexamples_;

  ifs.close();
}

void FastText::supervisedTrain(Model& model,
                                const std::vector<int32_t>& line,
                                const std::vector<int32_t>& labels,
                                float lr) {
  if (labels.empty() || line.empty()) return;

  std::vector<int32_t> input;
  for (int32_t id : line) {
    const auto& subwords = dict_->getSubwords(id);
    input.insert(input.end(), subwords.begin(), subwords.end());
  }

  if (args_->wordNgrams > 1) {
    addWordNgrams(input, line, args_->wordNgrams);
  }

  if (input.empty()) return;

  std::uniform_int_distribution<int32_t> uniform(0, (int32_t)labels.size() - 1);
  int32_t targetIdx = uniform(model.rng_);
  model.update(input, labels, targetIdx, lr);
}

void FastText::skipgramTrain(Model& model,
                              const std::vector<int32_t>& line,
                              float lr) {
  std::uniform_int_distribution<int32_t> uniform(1, args_->ws);
  for (int32_t w = 0; w < (int32_t)line.size(); w++) {
    int32_t boundary = uniform(model.rng_);
    const auto& ngrams = dict_->getSubwords(line[w]);
    for (int32_t c = -boundary; c <= boundary; c++) {
      if (c == 0 || w + c < 0 || w + c >= (int32_t)line.size()) continue;
      model.update(ngrams, {line[w + c]}, 0, lr);
    }
  }
}

void FastText::cbowTrain(Model& model,
                          const std::vector<int32_t>& line,
                          float lr) {
  std::uniform_int_distribution<int32_t> uniform(1, args_->ws);
  for (int32_t w = 0; w < (int32_t)line.size(); w++) {
    int32_t boundary = uniform(model.rng_);
    std::vector<int32_t> bow;
    for (int32_t c = -boundary; c <= boundary; c++) {
      if (c == 0 || w + c < 0 || w + c >= (int32_t)line.size()) continue;
      const auto& ngrams = dict_->getSubwords(line[w + c]);
      bow.insert(bow.end(), ngrams.begin(), ngrams.end());
    }
    if (bow.empty()) continue;
    model.update(bow, {line[w]}, 0, lr);
  }
}

void FastText::addWordNgrams(std::vector<int32_t>& line,
                              const std::vector<int32_t>& words,
                              int32_t n) const {
  for (int32_t i = 0; i < (int32_t)words.size(); i++) {
    uint64_t h = words[i];
    for (int32_t j = i + 1; j < (int32_t)words.size() && j < i + n; j++) {
      h = h * 116049371 + words[j];
      if (args_->bucket > 0) {
        int32_t idx = dict_->nwords() + (h % args_->bucket);
        if (idx < (int32_t)input_->rows()) {
          line.push_back(idx);
        }
      }
    }
  }
}

void FastText::loadModel(const std::string& filename) {
  std::ifstream ifs(filename, std::ios::binary);
  if (!ifs.is_open()) {
    throw std::invalid_argument(filename + " cannot be opened for loading!");
  }

  int32_t magic, version;
  ifs.read(reinterpret_cast<char*>(&magic), sizeof(int32_t));
  ifs.read(reinterpret_cast<char*>(&version), sizeof(int32_t));

  if (magic != FASTTEXT_FILEFORMAT_MAGIC_INT32) {
    throw std::invalid_argument("Model file has wrong file format!");
  }
  if (version > FASTTEXT_VERSION) {
    throw std::invalid_argument("Model file has wrong file format! (version)");
  }

  args_ = std::make_shared<Args>();
  args_->load(ifs);

  dict_ = std::make_shared<Dictionary>(args_, ifs);

  bool quant_input;
  ifs.read(reinterpret_cast<char*>(&quant_input), sizeof(bool));
  if (quant_input) {
    quant_ = true;
    qinput_ = std::make_shared<QuantMatrix>();
    qinput_->load(ifs);
  } else {
    input_ = std::make_shared<DenseMatrix>();
    input_->load(ifs);
  }

  bool quant_output;
  ifs.read(reinterpret_cast<char*>(&quant_output), sizeof(bool));
  if (quant_output) {
    qoutput_ = std::make_shared<QuantMatrix>();
    qoutput_->load(ifs);
    // Create a dense output for the model if needed
    output_ = std::make_shared<DenseMatrix>(qoutput_->rows(), qoutput_->cols());
  } else {
    output_ = std::make_shared<DenseMatrix>();
    output_->load(ifs);
  }

  ifs.close();

  // For quantized input, we need to create a DenseMatrix proxy
  if (quant_input && !input_) {
    // Expand qinput to dense
    input_ = std::make_shared<DenseMatrix>(qinput_->rows(), qinput_->cols());
    Vector vec(qinput_->cols());
    for (int64_t i = 0; i < qinput_->rows(); i++) {
      vec.zero();
      qinput_->addToVector(vec, i);
      for (int64_t j = 0; j < qinput_->cols(); j++) {
        input_->at(i, j) = vec[j];
      }
    }
  }

  initModel();
}

void FastText::saveModel(const std::string& filename) {
  std::string fn = filename + ".bin";
  std::ofstream ofs(fn, std::ios::binary);
  if (!ofs.is_open()) {
    throw std::invalid_argument(fn + " cannot be opened for saving!");
  }

  ofs.write(reinterpret_cast<const char*>(&FASTTEXT_FILEFORMAT_MAGIC_INT32), sizeof(int32_t));
  ofs.write(reinterpret_cast<const char*>(&FASTTEXT_VERSION), sizeof(int32_t));

  args_->save(ofs);
  dict_->save(ofs);

  bool quant_input = false;
  ofs.write(reinterpret_cast<const char*>(&quant_input), sizeof(bool));
  input_->save(ofs);

  bool quant_output = false;
  ofs.write(reinterpret_cast<const char*>(&quant_output), sizeof(bool));
  output_->save(ofs);

  ofs.close();
}

void FastText::saveVectors(const std::string& filename) {
  std::string fn = filename + ".vec";
  std::ofstream ofs(fn);
  if (!ofs.is_open()) {
    throw std::invalid_argument(fn + " cannot be opened for saving!");
  }

  int32_t nwords = dict_->nwords();
  ofs << nwords << " " << args_->dim << "\n";

  Vector vec(args_->dim);
  for (int32_t i = 0; i < nwords; i++) {
    std::string word = dict_->getWord(i);
    getWordVector(vec, word);
    ofs << word << " " << vec << "\n";
  }

  ofs.close();
}

void FastText::saveOutput(const std::string& filename) {
  std::string fn = filename + ".output";
  std::ofstream ofs(fn);
  if (!ofs.is_open()) {
    throw std::invalid_argument(fn + " cannot be opened for saving!");
  }

  int64_t n = output_->rows();
  int64_t d = output_->cols();
  ofs << n << " " << d << "\n";
  for (int64_t i = 0; i < n; i++) {
    std::string word;
    if (args_->model == model_name::sup) {
      word = dict_->getLabel(i);
    } else {
      word = dict_->getWord(i);
    }
    ofs << word << " ";
    for (int64_t j = 0; j < d; j++) {
      if (j > 0) ofs << " ";
      ofs << output_->at(i, j);
    }
    ofs << "\n";
  }

  ofs.close();
}

void FastText::getWordVector(Vector& vec, const std::string& word) const {
  vec.zero();

  const std::vector<int32_t>& ngrams = dict_->getSubwords(word);

  if (ngrams.empty()) return;

  for (int32_t i : ngrams) {
    if (i >= 0 && i < (int32_t)input_->rows()) {
      vec.addRow(*input_, i);
    }
  }
  vec.mul(1.0f / ngrams.size());
}

void FastText::getSentenceVector(std::istream& in, Vector& svec) const {
  svec.zero();
  if (args_->model == model_name::sup) {
    std::vector<int32_t> line, labels;
    dict_->getLine(in, line, labels);

    std::vector<int32_t> input;
    for (int32_t id : line) {
      const auto& subwords = dict_->getSubwords(id);
      input.insert(input.end(), subwords.begin(), subwords.end());
    }

    if (!input.empty()) {
      for (int32_t i : input) {
        if (i >= 0 && i < (int32_t)input_->rows()) {
          svec.addRow(*input_, i);
        }
      }
      svec.mul(1.0f / input.size());
    }
  } else {
    Vector vec(args_->dim);
    std::string word;
    int32_t count = 0;
    while (in >> word) {
      getWordVector(vec, word);
      double n = vec.norm();
      if (n > 0) {
        vec.mul(1.0f / n);
        svec.addVector(vec);
        count++;
      }
    }
    if (count > 0) svec.mul(1.0f / count);
  }
}

void FastText::printWordVectors(std::istream& in, std::ostream& out) const {
  std::string word;
  Vector vec(args_->dim);
  while (in >> word) {
    getWordVector(vec, word);
    out << word << " " << vec << "\n";
  }
}

void FastText::printSentenceVectors(std::istream& in, std::ostream& out) const {
  if (args_->model == model_name::sup) {
    while (!in.eof()) {
      Vector svec(args_->dim);
      std::string line;
      std::getline(in, line);
      if (line.empty() && in.eof()) break;
      std::istringstream iss(line);
      std::vector<int32_t> words, labels;
      dict_->getLine(iss, words, labels);

      std::vector<int32_t> input;
      for (int32_t id : words) {
        const auto& subwords = dict_->getSubwords(id);
        input.insert(input.end(), subwords.begin(), subwords.end());
      }

      if (!input.empty()) {
        for (int32_t i : input) {
          if (i >= 0 && i < (int32_t)input_->rows()) {
            svec.addRow(*input_, i);
          }
        }
        svec.mul(1.0f / input.size());
      }
      out << svec << "\n";
    }
  } else {
    while (!in.eof()) {
      Vector svec(args_->dim);
      Vector vec(args_->dim);
      std::string line;
      std::getline(in, line);
      if (line.empty() && in.eof()) break;
      std::istringstream iss(line);
      std::string word;
      int32_t count = 0;
      while (iss >> word) {
        getWordVector(vec, word);
        double n = vec.norm();
        if (n > 0) {
          vec.mul(1.0f / n);
          svec.addVector(vec);
          count++;
        }
      }
      if (count > 0) svec.mul(1.0f / count);
      out << svec << "\n";
    }
  }
}

void FastText::printNgrams(const std::string& word, std::ostream& out) const {
  std::vector<int32_t> ngrams;
  std::vector<std::string> substrings;
  dict_->getSubwords(word, ngrams, substrings);

  Vector vec(args_->dim);
  for (size_t i = 0; i < ngrams.size(); i++) {
    vec.zero();
    if (ngrams[i] >= 0 && ngrams[i] < (int32_t)input_->rows()) {
      vec.addRow(*input_, ngrams[i]);
    }
    out << substrings[i] << " " << vec << "\n";
  }
}

std::vector<std::pair<float, std::string>> FastText::findNN(
    const Vector& queryVec,
    int32_t k,
    const std::unordered_set<std::string>& bannedWords) const {

  int32_t nwords = dict_->nwords();

  Vector vec(args_->dim);
  std::vector<std::pair<float, std::string>> results;
  results.reserve(nwords);

  double qnorm = queryVec.norm();
  if (qnorm <= 0) return results;

  for (int32_t i = 0; i < nwords; i++) {
    std::string word = dict_->getWord(i);
    if (bannedWords.count(word)) continue;

    getWordVector(vec, word);
    double norm = vec.norm();
    if (norm <= 0) continue;

    float sim = 0.0f;
    for (int32_t j = 0; j < args_->dim; j++) {
      sim += vec[j] * queryVec[j];
    }
    sim /= (float)(norm * qnorm);

    results.push_back({sim, word});
  }

  std::sort(results.begin(), results.end(), [](const auto& a, const auto& b) {
    return a.first > b.first;
  });

  if ((int32_t)results.size() > k) {
    results.resize(k);
  }

  return results;
}

void FastText::nn(std::istream& in, std::ostream& out, int32_t k) const {
  std::string word;
  Vector queryVec(args_->dim);

  while (true) {
    out << "Query word? " << std::flush;
    if (!(in >> word)) break;

    getWordVector(queryVec, word);

    std::unordered_set<std::string> banned = {word};
    auto results = findNN(queryVec, k, banned);

    for (const auto& r : results) {
      out << r.second << " " << r.first << "\n";
    }
  }
  out << std::flush;
}

void FastText::analogies(std::istream& in, std::ostream& out, int32_t k) const {
  std::string wordA, wordB, wordC;
  Vector a(args_->dim), b(args_->dim), c(args_->dim), query(args_->dim);

  while (true) {
    out << "Query triplet (A - B + C)? " << std::flush;
    if (!(in >> wordA >> wordB >> wordC)) break;

    getWordVector(a, wordA);
    getWordVector(b, wordB);
    getWordVector(c, wordC);

    query.zero();
    query.addVector(a, 1.0f);
    query.addVector(b, -1.0f);
    query.addVector(c, 1.0f);

    std::unordered_set<std::string> banned = {wordA, wordB, wordC};
    auto results = findNN(query, k, banned);

    for (const auto& r : results) {
      out << r.second << " " << r.first << "\n";
    }
  }
}

std::vector<std::pair<float, std::string>> FastText::getPredictions(
    const std::vector<int32_t>& input,
    int32_t k,
    float threshold) const {

  if (input.empty()) return {};

  // Compute hidden
  model_->hidden_.zero();
  for (int32_t i : input) {
    if (i >= 0 && i < (int32_t)input_->rows()) {
      model_->hidden_.addRow(*input_, i);
    }
  }
  model_->hidden_.mul(1.0f / input.size());

  Predictions heap;
  model_->loss_->predict(k, threshold, heap, *model_);

  std::sort(heap.begin(), heap.end(), [](const auto& a, const auto& b) {
    return a.first > b.first;
  });

  std::vector<std::pair<float, std::string>> results;
  for (const auto& p : heap) {
    if (p.second >= 0 && p.second < dict_->nlabels()) {
      results.push_back({p.first, dict_->getLabel(p.second)});
    }
  }
  return results;
}

std::vector<std::pair<float, std::string>> FastText::getPredictions(
    std::istream& in,
    int32_t k,
    float threshold) const {

  std::vector<int32_t> words, labels;
  dict_->getLine(in, words, labels);

  std::vector<int32_t> input;
  for (int32_t id : words) {
    const auto& subwords = dict_->getSubwords(id);
    input.insert(input.end(), subwords.begin(), subwords.end());
  }

  if (args_->wordNgrams > 1 && !words.empty()) {
    addWordNgrams(const_cast<std::vector<int32_t>&>(input), words, args_->wordNgrams);
  }

  return getPredictions(input, k, threshold);
}

void FastText::predict(std::istream& in, std::ostream& out, int32_t k, float threshold, bool printProb) const {
  while (!in.eof()) {
    auto predictions = getPredictions(in, k, threshold);
    if (in.eof() && predictions.empty()) break;

    for (size_t i = 0; i < predictions.size(); i++) {
      if (i > 0) out << " ";
      out << predictions[i].second;
      if (printProb) out << " " << predictions[i].first;
    }
    out << "\n";
  }
}

void FastText::test(std::istream& in, int32_t k, float threshold, std::ostream& out) const {
  int32_t nexamples = 0;
  double precision = 0.0;
  int64_t nlabels_total = 0;

  std::vector<int32_t> line, labels;
  while (!in.eof()) {
    dict_->getLine(in, line, labels);
    if (labels.empty() || line.empty()) continue;

    std::vector<int32_t> input;
    for (int32_t id : line) {
      const auto& subwords = dict_->getSubwords(id);
      input.insert(input.end(), subwords.begin(), subwords.end());
    }

    if (args_->wordNgrams > 1 && !line.empty()) {
      addWordNgrams(const_cast<std::vector<int32_t>&>(input), line, args_->wordNgrams);
    }

    if (input.empty()) continue;

    auto predictions = getPredictions(input, k, threshold);

    for (const auto& p : predictions) {
      for (int32_t l : labels) {
        if (dict_->getLabel(l) == p.second) {
          precision++;
          break;
        }
      }
    }

    nexamples++;
    nlabels_total += labels.size();
  }

  out << "N\t" << nexamples << "\n";
  if (nexamples > 0) {
    out << std::fixed << std::setprecision(3) 
        << "P@" << k << "\t" << precision / (nexamples * k) << "\n";
    out << "R@" << k << "\t" << precision / nlabels_total << "\n";
  }
}

void FastText::testLabel(std::istream& in, int32_t k, float threshold, std::ostream& out) const {
  int32_t nlabels = dict_->nlabels();

  std::vector<int32_t> tp(nlabels, 0);
  std::vector<int32_t> fp(nlabels, 0);
  std::vector<int32_t> fn(nlabels, 0);
  int32_t nexamples = 0;
  double precision_sum = 0.0;

  std::vector<int32_t> line, labels;
  while (!in.eof()) {
    dict_->getLine(in, line, labels);
    if (labels.empty() || line.empty()) continue;

    std::vector<int32_t> input;
    for (int32_t id : line) {
      const auto& subwords = dict_->getSubwords(id);
      input.insert(input.end(), subwords.begin(), subwords.end());
    }

    if (args_->wordNgrams > 1 && !line.empty()) {
      addWordNgrams(const_cast<std::vector<int32_t>&>(input), line, args_->wordNgrams);
    }

    if (input.empty()) continue;

    auto predictions = getPredictions(input, k, threshold);
    nexamples++;

    std::set<int32_t> labelSet(labels.begin(), labels.end());

    for (const auto& p : predictions) {
      int32_t id = -1;
      for (int32_t j = 0; j < nlabels; j++) {
        if (dict_->getLabel(j) == p.second) {
          id = j;
          break;
        }
      }
      if (id < 0) continue;

      if (labelSet.count(id)) {
        tp[id]++;
        precision_sum++;
      } else {
        fp[id]++;
      }
    }

    for (int32_t l : labels) {
      bool found = false;
      for (const auto& p : predictions) {
        if (dict_->getLabel(l) == p.second) { found = true; break; }
      }
      if (!found) fn[l]++;
    }
  }

  for (int32_t i = 0; i < nlabels; i++) {
    double p = (tp[i] + fp[i] > 0) ? (double)tp[i] / (tp[i] + fp[i]) : 0.0;
    double r = (tp[i] + fn[i] > 0) ? (double)tp[i] / (tp[i] + fn[i]) : 0.0;
    double f1 = (p + r > 0) ? 2.0 * p * r / (p + r) : 0.0;
    out << std::fixed << std::setprecision(6)
        << "F1-Score : " << f1
        << "  Precision : " << p
        << "  Recall : " << r
        << "   " << dict_->getLabel(i) << "\n";
  }

  out << "N\t" << nexamples << "\n";
  if (nexamples > 0) {
    out << std::fixed << std::setprecision(3)
        << "P@" << k << "\t" << precision_sum / (nexamples * k) << "\n";
    out << "R@" << k << "\t" << precision_sum / nexamples << "\n";
  }
}

void FastText::quantize(const Args& qargs) {
  std::string binfile = qargs.output + ".bin";
  loadModel(binfile);

  args_->cutoff = qargs.cutoff;
  args_->retrain = qargs.retrain;
  args_->qnorm = qargs.qnorm;
  args_->qout = qargs.qout;
  args_->dsub = qargs.dsub;

  // Quantize input matrix
  qinput_ = std::make_shared<QuantMatrix>(std::move(*input_), args_->dsub, args_->qnorm);
  input_ = nullptr;

  // Save quantized model
  std::string fn = qargs.output + ".ftz";
  std::ofstream ofs(fn, std::ios::binary);
  if (!ofs.is_open()) {
    throw std::invalid_argument(fn + " cannot be opened for saving!");
  }

  ofs.write(reinterpret_cast<const char*>(&FASTTEXT_FILEFORMAT_MAGIC_INT32), sizeof(int32_t));
  ofs.write(reinterpret_cast<const char*>(&FASTTEXT_VERSION), sizeof(int32_t));

  args_->save(ofs);
  dict_->save(ofs);

  bool quant_input_flag = true;
  ofs.write(reinterpret_cast<const char*>(&quant_input_flag), sizeof(bool));
  qinput_->save(ofs);

  if (args_->qout) {
    auto qout = std::make_shared<QuantMatrix>(std::move(*output_), args_->dsub, false);
    bool qout_flag = true;
    ofs.write(reinterpret_cast<const char*>(&qout_flag), sizeof(bool));
    qout->save(ofs);
  } else {
    bool qout_flag = false;
    ofs.write(reinterpret_cast<const char*>(&qout_flag), sizeof(bool));
    output_->save(ofs);
  }

  ofs.close();
  quant_ = true;
}

void FastText::dumpArgs(std::ostream& out) const {
  args_->dump(out);
}

void FastText::dumpDict(std::ostream& out) const {
  dict_->dump(out);
}

void FastText::dumpInput(std::ostream& out) const {
  if (quant_ && qinput_) {
    qinput_->dump(out);
  } else if (input_) {
    input_->dump(out);
  }
}

void FastText::dumpOutput(std::ostream& out) const {
  if (args_->qout && qoutput_) {
    qoutput_->dump(out);
  } else if (output_) {
    output_->dump(out);
  }
}

void FastText::loadVectors(const std::string& filename) {
  std::ifstream in(filename);
  if (!in.is_open()) {
    throw std::invalid_argument(filename + " cannot be opened for loading!");
  }

  int64_t n, dim;
  in >> n >> dim;

  // Initialize matrices first
  initMatrices();

  std::string word;
  std::vector<float> vec(dim);
  while (in >> word) {
    int32_t id = dict_->getId(word);
    for (int64_t j = 0; j < dim; j++) {
      in >> vec[j];
    }
    if (id < 0 || id >= dict_->nwords()) continue;
    int32_t min_dim = std::min((int64_t)args_->dim, dim);
    for (int32_t j = 0; j < min_dim; j++) {
      input_->at(id, j) = vec[j];
    }
  }

  in.close();
}

