Args parseTrainArgs(const std::vector<std::string>& args, model_name model) {
  Args a;
  a.setDefaults(model);

  // Parse flag-value pairs
  for (size_t i = 0; i < args.size(); i++) {
    if (args[i].empty() || args[i][0] != '-') {
      throw std::invalid_argument("Provided argument without a dash! Usage: word2vec [-arguments]");
    }
    std::string arg = args[i].substr(1);
    if (!arg.empty() && arg[0] == '-') arg = arg.substr(1); // double dash

    if (arg == "input") {
      a.input = args.at(++i);
    } else if (arg == "output") {
      a.output = args.at(++i);
    } else if (arg == "lr") {
      a.lr = std::stod(args.at(++i));
    } else if (arg == "lrUpdateRate") {
      a.lrUpdateRate = std::stoi(args.at(++i));
    } else if (arg == "dim") {
      a.dim = std::stoi(args.at(++i));
    } else if (arg == "ws") {
      a.ws = std::stoi(args.at(++i));
    } else if (arg == "epoch") {
      a.epoch = std::stoi(args.at(++i));
    } else if (arg == "minCount") {
      a.minCount = std::stoi(args.at(++i));
    } else if (arg == "minCountLabel") {
      a.minCountLabel = std::stoi(args.at(++i));
    } else if (arg == "neg") {
      a.neg = std::stoi(args.at(++i));
    } else if (arg == "wordNgrams") {
      a.wordNgrams = std::stoi(args.at(++i));
    } else if (arg == "loss") {
      std::string lossStr = args.at(++i);
      if (lossStr == "hs") a.loss = loss_name::hs;
      else if (lossStr == "ns") a.loss = loss_name::ns;
      else if (lossStr == "softmax") a.loss = loss_name::softmax;
      else if (lossStr == "one-vs-all" || lossStr == "ova") a.loss = loss_name::ova;
      else throw std::invalid_argument("Unknown loss: " + lossStr);
    } else if (arg == "bucket") {
      a.bucket = std::stoi(args.at(++i));
    } else if (arg == "minn") {
      a.minn = std::stoi(args.at(++i));
    } else if (arg == "maxn") {
      a.maxn = std::stoi(args.at(++i));
    } else if (arg == "thread") {
      a.thread = std::stoi(args.at(++i));
    } else if (arg == "t") {
      a.t = std::stod(args.at(++i));
    } else if (arg == "label") {
      a.label = args.at(++i);
    } else if (arg == "verbose") {
      a.verbose = std::stoi(args.at(++i));
    } else if (arg == "pretrainedVectors") {
      a.pretrainedVectors = args.at(++i);
    } else if (arg == "saveOutput") {
      std::string val = args.at(++i);
      a.saveOutput = (val == "1" || val == "true");
    } else if (arg == "seed") {
      a.seed = std::stoi(args.at(++i));
    } else if (arg == "autotune-validation") {
      a.autotuneValidationFile = args.at(++i);
    } else if (arg == "autotune-metric") {
      a.autotuneMetric = args.at(++i);
    } else if (arg == "autotune-predictions") {
      a.autotunePredictions = std::stoi(args.at(++i));
    } else if (arg == "autotune-duration") {
      a.autotuneDuration = std::stoi(args.at(++i));
    } else if (arg == "autotune-modelsize") {
      a.autotuneModelSize = args.at(++i);
    } else if (arg == "cutoff") {
      a.cutoff = std::stoi(args.at(++i));
    } else if (arg == "retrain") {
      std::string val = args.at(++i);
      a.retrain = (val == "1" || val == "true");
    } else if (arg == "qnorm") {
      std::string val = args.at(++i);
      a.qnorm = (val == "1" || val == "true");
    } else if (arg == "qout") {
