    std::cerr << "usage: fasttext print-sentence-vectors <model>\n";
    exit(1);
  }

  FastText fasttext;
  try {
    fasttext.loadModel(args[1]);
  } catch (std::exception& e) {
    std::cerr << e.what() << std::endl;
    exit(1);
  }

  fasttext.printSentenceVectors(std::cin, std::cout);
}

void printNgrams(const std::vector<std::string>& args) {
  if (args.size() < 3) {
    std::cerr << "usage: fasttext print-ngrams <model> <word>\n";
    exit(1);
  }

  FastText fasttext;
  try {
    fasttext.loadModel(args[1]);
  } catch (std::exception& e) {
    std::cerr << e.what() << std::endl;
    exit(1);
  }

  fasttext.printNgrams(args[2], std::cout);
}

void nn(const std::vector<std::string>& args) {
  if (args.size() < 3) {
    std::cerr << "usage: fasttext nn <model> <k>\n";
    exit(1);
  }

  FastText fasttext;
  try {
    fasttext.loadModel(args[1]);
  } catch (std::exception& e) {
    std::cerr << e.what() << std::endl;
    exit(1);
  }

  int32_t k = std::stoi(args[2]);
  fasttext.nn(std::cin, std::cout, k);
}

void analogies(const std::vector<std::string>& args) {
  if (args.size() < 3) {
    std::cerr << "usage: fasttext analogies <model> <k>\n";
    exit(1);
