# but keep it for getLine(words, rng) which is used for training

# Let me modify the labels version to NOT auto-reset
cat > /tmp/fix_getline.py << 'EOF'
import re

with open('/workspace/src/dictionary.cc', 'r') as f:
    content = f.read()

# Find the getLine with labels and remove the auto-reset
old = '''int32_t Dictionary::getLine(std::istream& in,
                             std::vector<int32_t>& words,
                             std::vector<int32_t>& labels) const {
  std::string token;
  int32_t ntokens = 0;

  words.clear();
  labels.clear();

  if (in.eof()) {
    in.clear();
    in.seekg(0, std::ios::beg);
  }'''

new = '''int32_t Dictionary::getLine(std::istream& in,
                             std::vector<int32_t>& words,
                             std::vector<int32_t>& labels) const {
  std::string token;
  int32_t ntokens = 0;

  words.clear();
  labels.clear();'''

content = content.replace(old, new)

with open('/workspace/src/dictionary.cc', 'w') as f:
    f.write(content)

print("Done")
EOF
