# The issue: readWord returns true for end-of-line (empty word!)
# Line 181: if (c == '\n') return true; // end of line
# This returns true even when there's no word (empty line or just newline)
# Then in getLine, the empty word doesn't match anything, so words stays empty
# getLine loops until readWord returns false... but for lines with only whitespace
# readWord returns true with empty word

# Wait, the actual issue is different. After the input "great acting\n":
# 1. readWord reads 'g' then 'reat ' -> "great", puts '\n' back... no wait
# Actually the flow is:
# - First call: reads non-space chars -> "great", hits space, stops
# - Second call (from getLine loop): reads space, hits '\n' -> puts '\n' back... 
#   Wait no: if we hit space (not '\n') we stop. But ' ' is a space that's not '\n'.
#   So we read "acting" (stops at '\n'), then sputbackc('\n')
# - Third call: reads '\n' at start (it was put back), returns true (end of line)
#   But word is empty! -> getLine gets empty token, which doesn't match anything
# - Fourth call: tries to read from EOF -> returns false
# - getLine returns

# So the third call with empty word is the issue!
# readWord returns true with empty word for end-of-line
# getLine needs to handle empty words

# Actually looking more carefully at the loop in getLine(words, labels):
# while (readWord(in, token)) {
#   ...
#   if (token == EOS) break;
# }
# When token is empty string, we just don't break and continue the outer loop

# But when we reach EOS marker, we break. 
# In supervised training, lines end with '\n', so we need to break at end-of-line

# The fix for readWord: when it returns true with an empty word (end-of-line),
# the caller (getLine) should use this as a "end of line" signal and break

# But getLine only breaks on EOS! Not on empty line.

# Actually - the readWord API seems intentionally designed:
# - Returns true with empty word = "this is end of line, move to next token on new line"
# - Returns false = EOF
# 
# But getLine doesn't use empty word as a line end signal.

# Let me look at how the real fastText handles this.
# In real fastText, the readWord returns true until EOF.
# The EOS marker "</s>" is appended to each line.

# Wait - in real fastText, the training text doesn't have EOS markers by default
# for supervised training! Each line ends with '\n' and that's used as line separator.

# The issue: for supervised getLine (words + labels version):
# readWord returns true with empty word when it reads a newline
# We should use empty word as "end of line" signal!

# Let me modify getLine(words, labels) to break on empty token:
cat > /tmp/fix_getline2.py << 'EOF'
with open('/workspace/src/dictionary.cc', 'r') as f:
    content = f.read()

# Fix the labels version of getLine to break on empty token
old = '''  while (readWord(in, token)) {
    int32_t h = find(token);
    int32_t id = word2int_[h];
    if (id >= 0) {
      ntokens++;
      if (getType(id) == entry_type::word) {
        words.push_back(id);
      } else if (getType(id) == entry_type::label) {
        labels.push_back(id - nwords_);
      }
    }
    if (token == EOS) break;
  }
  return ntokens;
}'''

new = '''  while (readWord(in, token)) {
    if (token.empty()) break; // end of line
    int32_t h = find(token);
    int32_t id = word2int_[h];
    if (id >= 0) {
      ntokens++;
      if (getType(id) == entry_type::word) {
        words.push_back(id);
      } else if (getType(id) == entry_type::label) {
        labels.push_back(id - nwords_);
      }
    }
    if (token == EOS) break;
  }
  return ntokens;
}'''

content = content.replace(old, new, 1)

with open('/workspace/src/dictionary.cc', 'w') as f:
    f.write(content)

print("Done")
EOF
