  std::istringstream ss("great acting\n");
  std::string token;
  int iter = 0;
  while (iter < 10) {
    bool r = readWord(ss, token);
    std::cerr << "readWord -> " << r << " token='" << token << "' eof=" << ss.eof() << "\n";
    if (!r) break;
    if (token.empty()) { std::cerr << "-> EOL\n"; break; }
    iter++;
  }

  std::cerr << "\npredict loop:\n";
  std::istringstream ss2("great acting\n");
  iter = 0;
  while (!ss2.eof() && iter < 10) {
