    bool hasData = false;
    while (readWord(ss2, token)) {
      if (token.empty()) break;
      hasData = true;
      std::cerr << "  word=" << token << "\n";
    }
    if (!hasData) { if (ss2.eof()) { std::cerr << "->EOF break\n"; break; } continue; }
    iter++;
  }
  return 0;
}
