#include <iostream>
#include <sstream>
#include <string>
#include <vector>

bool readWord(std::istream& in, std::string& word) {
  int c;
  word.clear();
  while ((c = in.get()) != EOF) {
    if (c == '\n') return true;
    if (!std::isspace(c)) { word += (char)c; break; }
  }
  if (in.eof()) return false;
  if (word.empty()) return true;
  while ((c = in.peek()) != EOF) {
    if (std::isspace(c)) break;
    in.get();
    word += (char)c;
  }
  return true;
}

void simGetLine(const std::string& input) {
  std::istringstream ss(input);
  std::string token;
  std::vector<std::string> words, labels;

  while (readWord(ss, token)) {
    if (token.empty()) break; // EOL
    if (token.substr(0,9) == "__label__") labels.push_back(token);
    else words.push_back(token);
  }

  std::cout << "words: ";
  for (auto& w : words) std::cout << w << " ";
  std::cout << "\nlabels: ";
  for (auto& l : labels) std::cout << l << " ";
  std::cout << "\neof: " << ss.eof() << "\n";
}

int main() {
  std::cout << "Test 1: single line\n";
  simGetLine("great acting\n");

  std::cout << "\nTest 2: first line of multi-line\n";
  {
    std::istringstream ss("__label__positive great acting\n__label__negative terrible\n");
    std::string token;
    std::vector<std::string> words, labels;
    while (readWord(ss, token)) {
      if (token.empty()) break;
      if (token.substr(0,9) == "__label__") labels.push_back(token);
      else words.push_back(token);
    }
    std::cout << "First getLine: words=";
    for (auto& w : words) std::cout << w << " ";
    std::cout << " labels=";
    for (auto& l : labels) std::cout << l << " ";
    std::cout << "\n";

    words.clear(); labels.clear();
    while (readWord(ss, token)) {
      if (token.empty()) break;
      if (token.substr(0,9) == "__label__") labels.push_back(token);
      else words.push_back(token);
    }
    std::cout << "Second getLine: words=";
    for (auto& w : words) std::cout << w << " ";
    std::cout << " labels=";
    for (auto& l : labels) std::cout << l << " ";
    std::cout << "\n";
  }

  // Test predict loop
  std::cout << "\nTest 3: predict loop\n";
  {
    std::istringstream ss("great acting\n");
    int iter = 0;
