#include <iostream>
#include <sstream>
#include <string>
#include <vector>

const std::string EOS = "</s>";

bool readWord(std::istream& in, std::string& word) {
  int c;
  word.clear();
  while (true) {
    c = in.peek();
    if (c == EOF) return false;
    if (c == '\n') { in.get(); word = EOS; return true; }
    if (!std::isspace(c)) break;
    in.get(); // consume horizontal whitespace
  }
  while (true) {
    c = in.peek();
    if (c == EOF || std::isspace(c)) break;
    in.get();
    word += (char)c;
  }
  return !word.empty();
}

int main() {
  {
    std::cout << "readFromFile simulation:\n";
    std::istringstream ss("great acting\nterrible boring\n");
    std::string w;
    while (readWord(ss, w)) {
      std::cout << "  token: '" << w << "' eof=" << ss.eof() << "\n";
    }
  }

  {
    std::cout << "\ngetLine(rng) simulation:\n";
    std::istringstream ss("great acting\nterrible boring\n");
    std::string w;
    for (int line = 0; line < 3; line++) {
      if (ss.eof()) { ss.clear(); ss.seekg(0); }
      std::vector<std::string> words;
      while (readWord(ss, w)) {
        if (w == EOS) break;
        words.push_back(w);
      }
      std::cout << "Line " << line << ": ";
      for (auto& x : words) std::cout << x << " ";
      std::cout << "(eof=" << ss.eof() << ")\n";
    }
  }

  {
    std::cout << "\npredict simulation:\n";
    std::istringstream ss("great acting\n");
    std::string w;
    int iter = 0;
    while (!ss.eof() && iter < 5) {
      std::vector<std::string> words;
      while (readWord(ss, w)) {
        if (w == EOS) break;
        words.push_back(w);
      }
      std::cout << "iter " << iter << " words=" << words.size() << " eof=" << ss.eof() << "\n";
      if (words.empty()) {
        if (ss.eof()) break;
        continue;
      }
      std::cout << "  predict!\n";
      iter++;
    }
  }

  return 0;
}
