# Now we need to set bucket=0 during training for supervised if user didn't specify it.
# Actually the simplest approach: in FastText::train(), after reading args,
# set bucket=0 if model is supervised and bucket hasn't been changed from default.
# But this is tricky.
# 
# Let me look at it differently: the original behavior seems to be:
# - Help shows bucket [2000000] for supervised
# - But actual training uses bucket=0 for supervised (from model dump)
# 
# This means: in the original, setDefaults for supervised does NOT set bucket.
# But during training initialization, the supervised model uses bucket=0 because
# minn=0 and maxn=0 (no char ngrams needed, so no bucket needed).
# 
# In our initMatrices(), we create input_ with size (nwords + bucket).
# If bucket=2000000 for supervised, we'd create a 2000000+ rows input matrix!
# That would be huge (200MB+). So the bucket MUST be 0 for supervised.
#
# Solution: in FastText::train(), override bucket=0 if model==sup and (minn==0 && maxn==0)
# OR: in initMatrices(), set effective bucket = (minn==0 && maxn==0) ? 0 : bucket.

# The cleanest solution: in FastText::train(), after parsing args:
# if (args.model == sup && args.minn == 0 && args.maxn == 0) args.bucket = 0;
# But we can't modify args since it's a const ref.
# 
# Actually: we can do this in the Args struct itself - compute effective bucket.
# Let me add a method:

cat > /tmp/fix_bucket.py << 'PYEOF'
with open('/workspace/src/fasttext.cc', 'r') as f:
    content = f.read()

old = '''  if (!args_->pretrainedVectors.empty()) {
    loadVectors(args_->pretrainedVectors);
  } else {
    initMatrices();
  }'''

new = '''  // For supervised without char ngrams, disable bucket
  if (args_->model == model_name::sup && args_->minn == 0 && args_->maxn == 0) {
    args_->bucket = 0;
  }

  if (!args_->pretrainedVectors.empty()) {
    loadVectors(args_->pretrainedVectors);
  } else {
    initMatrices();
  }'''

content = content.replace(old, new)
with open('/workspace/src/fasttext.cc', 'w') as f:
    f.write(content)
print("Done")
